we define the following excess risk as a surrogate of the population risk:
\begin{align}\label{eq:excess_risk}
\mathcal{E}(\overline{\mathbf{w}}_N) = L(\overline{\mathbf{w}}_N) - L(\mathbf w^*).

\label{ass1}
Let $\mathcal Q_i, i\in \{d,l,p,a,o\}$ be the coordinate-wise quantization operation for data feature, label, model parameter, activation, and output gradient, respectively. We assume that the quantization operation is unbiased, i.e., for any $\mathbf{u}$,
\begin{equation*}
    \mathbb{E}\left[\mathbf{\mathcal{Q}}_i(\mathbf{u})|\mathbf{u}\right]=\mathbf{u}.
\end{equation*}

\label{def:type_quantization}
Let $\mathcal{Q}$ be an unbiased quantization operation. We categorize it based on the structure of its error variance:
\begin{itemize}[leftmargin=*,nosep]
\item \textbf{Multiplicative quantization.} We call the quantization is $\epsilon$-multiplicative if the conditional second moment of quantization error is proportional to the outer product of raw data itself, i.e.,
    \begin{equation*}
        \mathbb{E}\left[\left(\mathcal{Q}(\mathbf{x})-\mathbf{x}\right)\left(\mathcal{Q}(\mathbf{x})-\mathbf{x}\right)^\top\bigg|\mathbf{x}\right]=\epsilon \mathbf{x}\mathbf{x}^\top.
    \end{equation*}
\item \textbf{Additive quantization.} We call the quantization is $\epsilon$-additive if the conditional second moment of quantization error is proportional to identity, i.e.,
    \begin{equation*}
        \mathbb{E}\left[\left(\mathcal{Q}(\mathbf{x})-\mathbf{x}\right)\left(\mathcal{Q}(\mathbf{x})-\mathbf{x}\right)^\top\bigg|\mathbf{x}\right]=\epsilon \mathbf{I}.
    \end{equation*}
\end{itemize}

The quantization error on data $\boldsymbol{\epsilon}^{(d)}$, on label $\epsilon^{(l)}$, on parameter $\boldsymbol{\epsilon}_t^{(p)}$ at time $t$, on activation $\boldsymbol{\epsilon}_t^{(a)}$ at time $t$ and on output gradient $\boldsymbol{\epsilon}_t^{(o)}$ at time $t$ are defined as follows.
\begin{gather*}
    \boldsymbol{\epsilon}^{(d)}:=\mathcal{Q}_d(\mathbf{x})-\mathbf{x},\quad \epsilon^{(l)}:=\mathcal{Q}_l(y)-y,\quad \boldsymbol{\epsilon}_t^{(p)}:=\mathcal{Q}_p(\mathbf{w}_t)-\mathbf{w}_t,\\ \boldsymbol{\epsilon}_t^{(a)}:=\mathcal{Q}_a(\mathbf{a}_t)-\mathbf{a}_t,\quad \boldsymbol{\epsilon}_t^{(o)}:=\mathcal{Q}_o(\mathbf{o}_t)-\mathbf{o}_t.
\end{gather*}

\label{ass: addd quantized}

Let $\mathbf H=\mathbb E[\mathbf x\mathbf x^\top]$ be the data covariance matrix and 
\begin{equation*}
    \mathbf{H}^{(q)}:=\mathbb{E}[\mathcal{Q}_d(\mathbf{x})\mathcal{Q}_d(\mathbf{x})^\top],\quad \mathbf{D}:=\mathbb{E}[(\mathcal{Q}_d(\mathbf{x})-\mathbf{x})(\mathcal{Q}_d(\mathbf{x})-\mathbf{x})^\top],
\end{equation*}
be the covariance matrices of the quantized data feature and quantization error of data covariance, respectively. Then we assume that $\mathrm{tr}(\mathbf{H})$ and $\mathrm{tr}(\mathbf{H}^{(q)})$ are finite.

Let $\mathbf H=\mathbb E[\mathbf x\mathbf x^\top]$ be the data covariance matrix and 
    \begin{equation*}
        \mathbf{H}^{(q)}:=\mathbb{E}[\mathcal{Q}_d(\mathbf{x})\mathcal{Q}_d(\mathbf{x})^\top],\quad \mathbf{D}:=\mathbb{E}[(\mathcal{Q}_d(\mathbf{x})-\mathbf{x})(\mathcal{Q}_d(\mathbf{x})-\mathbf{x})^\top],
    \end{equation*}
    be the covariance matrices of the quantized data feature and quantization error of data covariance, respectively.

\label{ass2}
    Let $\mathbf{x}^{(q)}=\mathcal{Q}_d(\mathbf{x})$. Then for any PSD matrix $\mathbf A$, there exists a constant $\alpha_B>0$ such that
    \begin{equation*}
        \mathbb{E}\left[{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\mathbf{A}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}\mathbf{A})\mathbf{H}^{(q)}.
    \end{equation*}

To extend the model noise assumption in \citet{zou2023benign} to the low-precision setting, we define the optimal model weight regarding the quantized data feature and label: 


\begin{equation*}
    {\mathbf{w}^{(q)}}^* = \mathrm{argmin}_\mathbf{w} \ \mathbb{E}\left[(\mathcal{Q}_l(y)-\langle \mathbf{w},\mathcal{Q}_d(\mathbf{x})\rangle)^2\right].
\end{equation*}

\label{ass3}
Assume there exists a positive constant $\sigma>0$ such that
\begin{equation*}
    \mathbb{E}\left[\xi^2\mathcal{Q}_d(\mathbf{x})\mathcal{Q}_d(\mathbf{x})^\top\right]\preceq\sigma^{2}\mathbf{H}^{(q)}.
\end{equation*}

\label{Theorem 4}
Consider general quantization. Denote $\mathbf{D}_1^{\mathbf{H}}=\mathbf{D}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{H}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{D}$, $\mathbf{D}_2^{\mathbf{H}}=\mathbf{H}(\mathbf{H}^{(q)})^{-1}\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\mathbf{D}(\mathbf{H}^{(q)})^{-1}\mathbf{H}$. Under Assumption \ref{ass1}, \ref{ass: addd quantized}, \ref{ass2} and \ref{ass3}, if the stepsize $\gamma < \frac{1}{\alpha_B \mathrm{tr}(\mathbf{H}^{(q)})}$, then it holds,
\begin{equation*}
    \mathbb{E}[\mathcal E(\overline{\mathbf{w}}_N)]\leq 2\mathrm{VarErr}+2\mathrm{BiasErr}+\mathrm{ApproxErr},

\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        &\mathrm{VarErr}\leq\frac{2\alpha_B\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)+{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),\\
        &\mathrm{BiasErr}\leq\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{ApproxErr}\leq\left\|\mathbf{w}^*\right\|_{\mathbf{D}_1^{\mathbf{H}}}^2+\|\mathbf{w}^*\|_{\mathbf{D}_2^\mathbf{H}}^2,


    \end{aligned}
\end{equation*}
with ${\sigma_G^{(q)}}^2=\frac{\sigma^2+\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}+\alpha_B\sup_t\mathbb{E}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right)\right]$.

\label{theorem new 2.5}
Under Assumption \ref{ass1}, \ref{ass: addd quantized}, \ref{ass2} and \ref{ass3}, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-additive, and the stepsize satisfies $\gamma < \frac{1}{\alpha_B [\mathrm{tr}(\mathbf{H})+d\epsilon_d]}$, then
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{ VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{align*}
        &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{\lambda_d+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{VarErr}\lesssim \frac{\alpha_B\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+\alpha_B \epsilon_p[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}{1-\gamma\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right).
\end{align*}

\label{Theorem 1}
Under Assumption \ref{ass1}, \ref{ass: addd quantized}, \ref{ass2} and \ref{ass3}, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, and the stepsize satisfies $\gamma < \frac{1}{ \alpha_B (1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}(\mathbf{H})}$, then the excess risk can be upper bounded as follows.
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{1+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{VarErr}\lesssim\left(\frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\sum_{i>k^*}\lambda_i^2\right) \frac{\frac{(1+\epsilon_o)\sigma^2}{B}+\alpha_B(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\left\|\mathbf{w}^*\right\|_\mathbf{H}^2}{1-\gamma\alpha_B(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}\left(\mathbf{H}\right)}.
    \end{aligned}
\end{equation*}

\label{coro:comparison}
To ensure that $\mathbb E[\mathcal E(\overline{\mathbf w}_N)]\lesssim R_0$, conditions on the quantization error are as follows:
\begin{itemize}[leftmargin=*,nosep]
\item For multiplicative quantization, under the conditions in Theorem \ref{Theorem 1}, we require
    \begin{equation*}
        \epsilon_d\lesssim 1\wedge \frac{R_0}{\|\mathbf{w}^*\|_{\mathbf{H}}^2},\quad\epsilon_o,\epsilon_a,\epsilon_p \lesssim  \left(\frac{\sigma^2}{B\alpha_B\|\mathbf{w}^*\|_\mathbf{H}^2}+\frac{\frac{1}{N\gamma}\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\|\mathbf{w}^*\|_\mathbf{H}^2}\right)\wedge 1.
    \end{equation*}
\item For additive quantization, under the conditions in Corollary \ref{theorem new 2.5}, we require
\begin{gather*}
        \epsilon_d\lesssim \sqrt{\frac{\frac{k_0^*}{N}+N\gamma^2\cdot\sum_{i>k_0^*}\lambda_i^2}{N\gamma^2(d-k_0^*)}}\wedge \frac{R_0\lambda_d}{\|\mathbf{w}^*\|_{\mathbf{H}}^2},\quad \epsilon_a,\epsilon_o\lesssim \sigma^2+B\alpha_B\left(\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right), \\ 
        \epsilon_p\lesssim \frac{\sigma^2}{B\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}+\frac{\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\mathrm{tr}(\mathbf{H})+d\epsilon_d}.
    \end{gather*}
\end{itemize}

\label{coro: case study}
    Taking expectation on $\mathbf{w}^*$, under Assumption \ref{assumption 1}, we have:
    \begin{itemize}[leftmargin=*,nosep]
        \item For multiplicative quantization, under the conditions in Theorem \ref{Theorem 1},
        \begin{equation*}
            \mathbb{E}\left[\mathcal{E}(\overline{\mathbf{w}}_N)\right]\lesssim\frac{\epsilon_d}{1+\epsilon_d}+d^{1-a}+N^{1/a-1}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)^{1/a}.
        \end{equation*}
        \item For additive quantization, under the conditions in Corollary \ref{theorem new 2.5},
        \begin{equation*}
            \begin{aligned}
                \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]\lesssim &\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\left(1+\frac{(d^a\epsilon_d)^2}{1+d^a\epsilon_d}\right)d^{1-a}+\frac{d^a\epsilon_d}{1+d^a\epsilon_d}\\
                +&\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)(1+d^a\epsilon_d)^{1/a}N^{1/a-1}.
            \end{aligned}
        \end{equation*}
    \end{itemize}

\label{update rule for eta_t}
    \begin{equation*}
        \boldsymbol{\eta}_t = \left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t) \right)\boldsymbol{\eta}_{t-1}+\gamma\frac{1}{B}{\mathcal{Q}_d(\mathbf{X}_t)}^\top \left[\boldsymbol{\xi}_t+\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)}-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\epsilon}_{t-1}^{(p)}\right],
    \end{equation*}
    where the quantization errors are
    \begin{equation*}
        \begin{aligned}
            \boldsymbol{\epsilon}_t^{(o)}:=&\mathcal{Q}_o\left(\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right)-\left[\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right],\\
            \boldsymbol{\epsilon}_t^{(a)}:=&\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)-\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1}),\\
            \boldsymbol{\epsilon}_{t-1}^{(p)}:=&\mathcal{Q}_p(\mathbf{w}_{t-1})-\mathbf{w}_{t-1},\\
            \boldsymbol{\xi}_t:=&\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_d(\mathbf{X}_t){\mathbf{w}^{(q)}}^*.
        \end{aligned}
    \end{equation*}

The lemma can be proved directly by the parameter update rule. By definition and the update rule of $\mathbf{w}_t$ (\ref{eq:SGD_quantized}),
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\eta}_t=&\mathbf{w}_t - {\mathbf{w}^{(q)}}^*\\
        =&\mathbf{w}_{t-1}-{\mathbf{w}^{(q)}}^*+\gamma \frac{1}{B}\mathcal{Q}_d(\mathbf{X}_t)^\top \mathcal{Q}_o\left(\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right)\\
        =&\boldsymbol{\eta}_{t-1}+\gamma \frac{1}{B}\mathcal{Q}_d(\mathbf{X}_t)^\top \mathcal{Q}_o\left(\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right).
    \end{aligned}
\end{equation*}
We then introduce quantization errors to better characterize each quantization operation $\mathcal{Q}(\cdot)$. In particular, define quantization erros:
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\epsilon}_t^{(o)}:=&\mathcal{Q}_o\left(\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right)-\left[\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right],\\
        \boldsymbol{\epsilon}_t^{(a)}:=&\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)-\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1}),\\
        \boldsymbol{\epsilon}_{t-1}^{(p)}:=&\mathcal{Q}_p(\mathbf{w}_{t-1})-\mathbf{w}_{t-1},\\
        \boldsymbol{\xi}_t:=&\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_d(\mathbf{X}_t){\mathbf{w}^{(q)}}^*.
    \end{aligned}
\end{equation*}
Then the update rule for the parameter deviation can be expressed as:
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\eta}_t = &\boldsymbol{\eta}_{t-1}+\gamma \frac{1}{B}\mathcal{Q}_d(\mathbf{X}_t)^\top \mathcal{Q}_o\left(\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right)\\
        =&\boldsymbol{\eta}_{t-1}+\gamma \mathcal{Q}_d(\mathbf{X}_t)^\top \frac{1}{B}\left[\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)\right]+\gamma \frac{1}{B}\mathcal{Q}_d(\mathbf{X}_t)^\top \boldsymbol{\epsilon}_t^{(o)}\\
        =&\boldsymbol{\eta}_{t-1}+\gamma \mathcal{Q}_d(\mathbf{X}_t)^\top \frac{1}{B}\left[\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right]+\gamma \frac{1}{B}\mathcal{Q}_d(\mathbf{X}_t)^\top (\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)})\\
        =&\boldsymbol{\eta}_{t-1}+\gamma \frac{1}{B}\mathcal{Q}_d(\mathbf{X}_t)^\top (\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)})+\gamma \mathcal{Q}_d(\mathbf{X}_t)^\top \frac{1}{B}\\
        &\left[\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_d(\mathbf{X}_t){\mathbf{w}^{(q)}}^*-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\eta}_{t-1}-\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})+\mathcal{Q}_d(\mathbf{X}_t)\mathbf{w}_{t-1}\right]\\
        =&\boldsymbol{\eta}_{t-1}+\gamma \mathcal{Q}_d(\mathbf{X}_t)^\top (\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)})+\gamma \mathcal{Q}_d(\mathbf{X}_t)^\top \frac{1}{B}\\
        &\left[\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_d(\mathbf{X}_t){\mathbf{w}^{(q)}}^*-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\eta}_{t-1}-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\epsilon}_{t-1}^{(p)}\right]\\
        =&\boldsymbol{\eta}_{t-1}+\gamma \frac{1}{B}\mathcal{Q}_d(\mathbf{X}_t)^\top (\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)}+\boldsymbol{\xi}_t)-\gamma \mathcal{Q}_d(\mathbf{X}_t)^\top \frac{1}{B}\left[\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\eta}_{t-1}+\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\epsilon}_{t-1}^{(p)}\right]\\
        =&\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t) \right)\boldsymbol{\eta}_{t-1}+\gamma\frac{1}{B}{\mathcal{Q}_d(\mathbf{X}_t)}^\top \left[\boldsymbol{\xi}_t+\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)}-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\epsilon}_{t-1}^{(p)}\right].
    \end{aligned}
\end{equation*}

\label{Excess Risk Decomposition}
    Under Assumption \ref{ass1} and Assumption \ref{ass: addd quantized},
    \begin{equation*}
        \begin{aligned}
            \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]=R_1+R_2+R_3+R_4,
        \end{aligned}
    \end{equation*}
    where
    \begin{equation*}
        \begin{aligned}
            R_1=&-\frac{1}{2}\mathbb{E}\left[\langle\overline{\mathbf{w}}_N, \mathcal{Q}_d(\mathbf{x})-\mathbf{x} \rangle^2\right],\\
            R_2=&\frac{1}{2}\langle\mathbf{H}^{(q)},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle,\\
            R_3=&\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})-\mathbf{x}\rangle^2\right],\\
            R_4=&\frac{1}{2}\left\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\right\rangle.
        \end{aligned}
    \end{equation*}

By the definition of the excess risk (\ref{eq:excess_risk}),
\begin{equation*}
    \begin{aligned}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]
        =&\frac{1}{2}\mathbb{E}\left[\left(y-\langle \overline{\mathbf{w}}_N,\mathbf{x} \rangle \right)^2\right]-\frac{1}{2}\mathbb{E}\left[\left(y-\langle \mathbf{w}^*,\mathbf{x} \rangle \right)^2\right]\\
        =&\underbrace{\frac{1}{2}\mathbb{E}\left[\left(y-\langle \overline{\mathbf{w}}_N,\mathbf{x} \rangle \right)^2\right]-\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle \overline{\mathbf{w}}_N,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]}_{E_1}\\
        +&\underbrace{\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle \overline{\mathbf{w}}_N,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]-\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]}_{E_2}\\
        +&\underbrace{\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]-\frac{1}{2}\mathbb{E}\left[\left(y-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x} \rangle \right)^2\right]}_{E_3}\\
        +&\underbrace{\frac{1}{2}\mathbb{E}\left[\left(y-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x} \rangle \right)^2\right]-\frac{1}{2}\mathbb{E}\left[\left(y-\langle \mathbf{w}^*,\mathbf{x} \rangle \right)^2\right]}_{E_4},
    \end{aligned}
\end{equation*}
where $E_1$ captures the gap of the averaged SGD iterate between the full-precision and quantized domains, $E_2$ characterizes the distance from the averaged SGD iterate to the quantized optimal solution within the quantized domain, $E_3$ represents the mismatch of the quantized optimal solution in full-precision data space and quantized data space and $E_4$ defines the discrepancy between the averaged SGD iterate and the quantized optimal solution in the full-precision domain. 

We would like to remark that the quantization operations $\mathcal{Q}_l(y)$ and $\mathcal{Q}_d(\mathbf{x})$ introduced in excess risk decomposition are independent of those quantization operators introduced in the training stage, i.e., $\overline{\mathbf{w}}_N$. Next, we analyze $E_1,E_2,E_3$ and $E_4$ respectively. These computations are mainly based on the first order optimality condition (\ref{definition w*}) and the unbiased quantization Assumption \ref{ass1}. For $E_4$,
\begin{equation}
    \label{eq: a3}
    \begin{aligned}
        E_4=&\frac{1}{2}\mathbb{E}\left[\left(y-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x} \rangle \right)^2\right]-\frac{1}{2}\mathbb{E}\left[\left(y-\langle \mathbf{w}^*,\mathbf{x} \rangle \right)^2\right]\\
        =&\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*,\mathbf{x} \rangle\cdot \left(2y-\langle {\mathbf{w}}^*+{\mathbf{w}^{(q)}}^*,\mathbf{x} \rangle\right)\right]\\
        =&\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*,\mathbf{x} \rangle^2\right]\\
        =&\frac{1}{2}\left({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*\right)^\top \mathbf{H} \left({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*\right)\\
        =&\frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle,
    \end{aligned}
\end{equation}
where the third equality uses the first order optimality condition that $\mathbb{E}_{(\mathbf{x},y)\sim\mathcal{D}}[(y-\langle{\mathbf{w}}^*,\mathbf{x}\rangle)\mathbf{x}]=\mathbf{0}$.

For $E_2$, similarly by the first order optimality condition (\ref{definition w*}) with respect to $\mathbf{w}^{(q)^*}$, it holds
\begin{equation}
    \label{eq: a4}
    \begin{aligned}
        E_2=&\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle \overline{\mathbf{w}}_N,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]-\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]\\
        =&\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*-\overline{\mathbf{w}}_N,\mathcal{Q}_d(\mathbf{x})\rangle \cdot \left(2\mathcal{Q}_l(y)-\langle {\mathbf{w}^{(q)}}^*+\overline{\mathbf{w}}_N,\mathcal{Q}_d(\mathbf{x}) \rangle\right) \right]\\
        =&\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*-\overline{\mathbf{w}}_N,\mathcal{Q}_d(\mathbf{x}) \rangle^2\right]\\
        =&\frac{1}{2}\langle\mathbf{H}^{(q)},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle.
    \end{aligned}
\end{equation}

For $E_3$,
\begin{equation*}
    \begin{aligned}
        E_3=&\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]-\frac{1}{2}\mathbb{E}\left[\left(y-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x} \rangle \right)^2\right]\\
        =&\frac{1}{2}\mathbb{E}\left[\left(\mathcal{Q}_l(y)-y-\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})-\mathbf{x}\rangle\right)\cdot \left(\mathcal{Q}_l(y)+y-\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})+\mathbf{x}\rangle\right)\right]\\
        =&\frac{1}{2}\mathbb{E}\left[\mathcal{Q}_l(y)^2-y^2+\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})-\mathbf{x}\rangle\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})+\mathbf{x}\rangle\right],
    \end{aligned}
\end{equation*}
where the last equality utilizes the unbiased quantization Assumption \ref{ass1}.

For $E_1$, similarly by the unbiased quantization Assumption \ref{ass1}, it holds
\begin{equation*}
    \begin{aligned}
        E_1=&\frac{1}{2}\mathbb{E}\left[\left(y-\langle \overline{\mathbf{w}}_N,\mathbf{x} \rangle \right)^2\right]-\frac{1}{2}\mathbb{E}\left[(\mathcal{Q}_l(y)-\langle \overline{\mathbf{w}}_N,\mathcal{Q}_d(\mathbf{x})\rangle)^2\right]\\
        =&\frac{1}{2}\mathbb{E}\left[\left(y-\mathcal{Q}_l(y)-\langle \overline{\mathbf{w}}_N ,\mathbf{x}-\mathcal{Q}_d(\mathbf{x}) \rangle\right)\cdot \left(y+\mathcal{Q}_l(y)-\langle \overline{\mathbf{w}}_N ,\mathbf{x}+\mathcal{Q}_d(\mathbf{x}) \rangle\right) \right]\\
        =&\frac{1}{2}\mathbb{E}\left[y^2-\mathcal{Q}_l(y)^2\right]+\frac{1}{2}\mathbb{E}\left[\langle \overline{\mathbf{w}}_N ,\mathbf{x}-\mathcal{Q}_d(\mathbf{x}) \rangle\langle \overline{\mathbf{w}}_N ,\mathbf{x}+\mathcal{Q}_d(\mathbf{x}) \rangle\right].
    \end{aligned}
\end{equation*}

Hence,
\begin{equation}
    \label{eq: a5}
    E_1+E_3=\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})-\mathbf{x}\rangle^2\right]-\frac{1}{2}\mathbb{E}\left[\langle \overline{\mathbf{w}}_N ,\mathbf{x}-\mathcal{Q}_d(\mathbf{x}) \rangle^2\right].
\end{equation}
Therefore, combining (\ref{eq: a3}), (\ref{eq: a4}) and (\ref{eq: a5}) we have
\begin{equation*}
    \begin{aligned}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]=&\frac{1}{2}\langle\mathbf{H}^{(q)},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle
        +\frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle\\
        +&\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})-\mathbf{x}\rangle^2\right]-\frac{1}{2}\mathbb{E}\left[\langle \overline{\mathbf{w}}_N ,\mathbf{x}-\mathcal{Q}_d(\mathbf{x}) \rangle^2\right].
    \end{aligned}
\end{equation*}

\label{Refine excess risk decomposition}
Under Assumption \ref{ass1} and Assumption \ref{ass: addd quantized}, if the stepsize $\gamma<\frac{1}{{\lambda}_1^{(q)}}$,
\begin{equation*}
    \begin{aligned}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]=&\underbrace{\frac{1}{2}\langle\mathbf{H},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle}_{R_N}+\mathrm{ApproxErr},
    \end{aligned}
\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        \mathrm{ApproxErr}=&\frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle\\
        +&\left({\mathbf{w}^{(q)}}^*\right)^\top\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*.
    \end{aligned}
\end{equation*}

By Lemma \ref{Excess Risk Decomposition},
\begin{equation*}
    \begin{aligned}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]=&\frac{1}{2}\langle\mathbf{H}^{(q)},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle\\
        +&\frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle\\
        +&\frac{1}{2}\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\mathcal{Q}_d(\mathbf{x})-\mathbf{x}\rangle^2\right]-\frac{1}{2}\mathbb{E}\left[\langle \overline{\mathbf{w}}_N ,\mathbf{x}-\mathcal{Q}_d(\mathbf{x}) \rangle^2\right].
    \end{aligned}
\end{equation*}
We then focus on $\frac{1}{2}\mathbb{E}\left[\langle \overline{\mathbf{w}}_N ,\mathbf{x}-\mathcal{Q}_d(\mathbf{x}) \rangle^2\right]$. Recall that
\begin{equation*}
    \overline{\mathbf{w}}_N=\overline{\mathbf{w}}_N-{\mathbf{w}^{(q)}}^*+{\mathbf{w}^{(q)}}^*=\overline{\boldsymbol{\eta}}_N+{\mathbf{w}^{(q)}}^*,
\end{equation*}
we have
\begin{equation*}
    \begin{aligned}
        \frac{1}{2}\mathbb{E}\left[\langle \overline{\mathbf{w}}_N ,\mathbf{x}-\mathcal{Q}_d(\mathbf{x}) \rangle^2\right]=&\frac{1}{2}\mathbb{E}\left[\overline{\mathbf{w}}_N^\top \left(\mathbf{H}^{(q)}-\mathbf{H}\right)\overline{\mathbf{w}}_N\right]\\
        =&\frac{1}{2}\mathbb{E}\left[\overline{\boldsymbol{\eta}}_N^\top \left(\mathbf{H}^{(q)}-\mathbf{H}\right)\overline{\boldsymbol{\eta}}_N\right]+\frac{1}{2}\mathbb{E}\left[\left({\mathbf{w}^{(q)}}^*\right)^\top \left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\right]\\
        +&\mathbb{E}\left[\overline{\boldsymbol{\eta}}_N^\top \left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\right].
    \end{aligned}
\end{equation*}
Hence,
\begin{equation}
    \label{eq: a6}
    \begin{aligned}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]=&\frac{1}{2}\langle\mathbf{H},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle
        +\frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle\\
        -&\mathbb{E}\left[\overline{\boldsymbol{\eta}}_N^\top \left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\right].
    \end{aligned}
\end{equation}
Noticing that by Lemma \ref{update rule for eta_t},
\begin{equation*}
    \boldsymbol{\eta}_t = \left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t) \right)\boldsymbol{\eta}_{t-1}+\gamma\frac{1}{B}{\mathcal{Q}_d(\mathbf{X}_t)}^\top \left[\boldsymbol{\xi}_t+\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)}-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\epsilon}_{t-1}^{(p)}\right],
\end{equation*}
it follows by Assumption \ref{ass1} that
\begin{equation*}
    \mathbb{E}\left[\boldsymbol{\eta}_t\right]=\mathbb{E}\left[\mathbb{E}\left[\boldsymbol{\eta}_t|\boldsymbol{\eta}_{t-1}\right]\right]=\mathbb{E}\left[\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)\boldsymbol{\eta}_{t-1}\right]=\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)\mathbb{E}\left[\boldsymbol{\eta}_{t-1}\right]=\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)^t\boldsymbol{\eta}_0.
\end{equation*}
Hence,
\begin{equation*}
    \begin{aligned}
        -\mathbb{E}\left[\overline{\boldsymbol{\eta}}_N^\top \left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\right]=&-\boldsymbol{\eta}_0^\top\frac{1}{N}\sum_{t=0}^{N-1}\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)^t\left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\\
        =&\left({\mathbf{w}^{(q)}}^*\right)^\top\frac{1}{N}\sum_{t=0}^{N-1}\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)^t\left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\\
        =&\left({\mathbf{w}^{(q)}}^*\right)^\top\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*.
    \end{aligned}
\end{equation*}
Combining (\ref{eq: a6}) completes the proof.

\label{lem: b1}
If there exists $\epsilon_d$ such that $\mathcal{Q}_d$ is $\epsilon_d$-multiplicative, under the assumptions and notations in Lemma \ref{Refine excess risk decomposition}, 
\begin{equation*}
    \mathrm{ApproxErr}\leq \frac{\epsilon_d^2}{2(1+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\epsilon_d}{(1+\epsilon_d)^2}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2.
\end{equation*}

Under multiplicative quantization, 
\begin{equation*}
    \mathbf{H}^{(q)}=(1+\epsilon_d)\mathbf{H}, \quad \mathbf{D}=\epsilon_d\mathbf{H}.
\end{equation*}
It follows by (\ref{eq: b1}) that 
\begin{equation*}
    \begin{aligned}
        \frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle=&\frac{1}{2}\|\mathbf{w}^*\|_{\mathbf{D}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{H}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{D}}^2=\frac{\epsilon_d^2}{2(1+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2.
    \end{aligned}
\end{equation*}
Similarly, by (\ref{eq: b2}),
\begin{equation*}
    \begin{aligned}
        &\left({\mathbf{w}^{(q)}}^*\right)^\top\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\\
        =&{\mathbf{w}^*}^\top \mathbf{H}(\mathbf{H}^{(q)})^{-1}\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\left(\mathbf{H}^{(q)}-\mathbf{H}\right)(\mathbf{H}^{(q)})^{-1}\mathbf{H}\mathbf{w}^*\\
        =&\frac{\epsilon_d}{N\gamma(1+\epsilon_d)}{\mathbf{w}^*}^\top \mathbf{H}(\mathbf{H}^{(q)})^{-1}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\mathbf{H}\mathbf{w}^*\\
        \leq& \frac{\epsilon_d}{N\gamma(1+\epsilon_d)^2} \left\|\mathbf{w}^*\right\|_\mathbf{H}^2\left\|(\mathbf{H}^{(q)})^{-1/2}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1/2}\right\|\\
        \leq&\frac{\epsilon_d}{N\gamma(1+\epsilon_d)^2} \left\|\mathbf{w}^*\right\|_\mathbf{H}^2\max_i \frac{\min\{1,N\gamma\lambda_i^{(q)}\}}{{\lambda}_i^{(q)}}\\
        \leq&\frac{\epsilon_d}{(1+\epsilon_d)^2}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2.
    \end{aligned}
\end{equation*}

\label{lem: b2}
If there exists $\epsilon_d$ such that $\mathcal{Q}_d$ is $\epsilon_d$-additive, under the assumptions and notations in Lemma \ref{Refine excess risk decomposition}, 
\begin{equation*}
    \mathrm{ApproxErr}\leq \frac{\epsilon_d^2}{2(\lambda_d+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\lambda_1\epsilon_d}{(\lambda_d+\epsilon_d)(\lambda_1+\epsilon_d)}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2.
\end{equation*}

Under additive quantization, 
\begin{equation*}
    \mathbf{H}^{(q)}=\mathbf{H}+\epsilon_d\mathbf{I}, \quad \mathbf{D}=\epsilon_d\mathbf{I}.
\end{equation*}
It follows by (\ref{eq: b1}) that 
\begin{equation*}
    \begin{aligned}
        \frac{1}{2}\langle\mathbf{H},({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\otimes({\mathbf{w}}^*-{\mathbf{w}^{(q)}}^*)\rangle=&\frac{1}{2}\|\mathbf{w}^*\|_{\mathbf{D}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{H}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{D}}^2\leq\frac{\epsilon_d^2}{2(\lambda_d+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2.
    \end{aligned}
\end{equation*}
Similarly, by (\ref{eq: b2}),
\begin{equation*}
    \begin{aligned}
        &\left({\mathbf{w}^{(q)}}^*\right)^\top\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\left(\mathbf{H}^{(q)}-\mathbf{H}\right){\mathbf{w}^{(q)}}^*\\
        =&{\mathbf{w}^*}^\top \mathbf{H}(\mathbf{H}^{(q)})^{-1}\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\left(\mathbf{H}^{(q)}-\mathbf{H}\right)(\mathbf{H}^{(q)})^{-1}\mathbf{H}\mathbf{w}^*\\
        \leq&\frac{\epsilon_d}{N\gamma(\lambda_d+\epsilon_d)}{\mathbf{w}^*}^\top \mathbf{H}(\mathbf{H}^{(q)})^{-1}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\mathbf{H}\mathbf{w}^*\\
        \leq& \frac{\lambda_1\epsilon_d}{N\gamma(\lambda_d+\epsilon_d)(\lambda_1+\epsilon_d)} \left\|\mathbf{w}^*\right\|_\mathbf{H}^2\left\|(\mathbf{H}^{(q)})^{-1/2}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1/2}\right\|\\
        \leq&\frac{\lambda_1\epsilon_d}{N\gamma(\lambda_d+\epsilon_d)(\lambda_1+\epsilon_d)} \left\|\mathbf{w}^*\right\|_\mathbf{H}^2\max_i \frac{\min\{1,N\gamma\lambda_i^{(q)}\}}{{\lambda}_i^{(q)}}\\
        \leq&\frac{\lambda_1\epsilon_d}{(\lambda_d+\epsilon_d)(\lambda_1+\epsilon_d)}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2.
    \end{aligned}
\end{equation*}

\label{Initial study of R_2}
Under Assumption \ref{ass1} and Assumption \ref{ass: addd quantized},
\begin{equation*}
    R_N^{(0)}\leq \frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t]\right\rangle.
\end{equation*}

Recall that by (\ref{eq: c1}),
\begin{equation*}
    R_N^{(0)}=\frac{1}{2}\langle\mathbf{H}^{(q)},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle,
\end{equation*}
we then focus on $\mathbb{E}[\overline{\boldsymbol{\eta}}_{N}\otimes\overline{\boldsymbol{\eta}}_{N}]$. By definition $\overline{\boldsymbol{\eta}}_{N}=\frac{1}{N}\sum_{t=0}^{N-1}\boldsymbol{\eta}_{t}$,
\begin{equation}
\label{D0}
    \begin{aligned}
        \mathbb{E}[\overline{\boldsymbol{\eta}}_{N}\otimes\overline{\boldsymbol{\eta}}_{N}]
        =&\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k]+\sum_{0\leq t<k\leq N-1}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k]\right) \\
        \preceq&\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_k]\right]+\sum_{0\leq t\leq k\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_t]\right]\right).
    \end{aligned}
\end{equation}
Note that by the unbiased Assumption \ref{ass1},
\begin{equation*}
    \mathbb{E}\left[\gamma{\mathcal{Q}_d(\mathbf{X}_t)}^\top \left(\boldsymbol{\epsilon}_t^{(o)}-\boldsymbol{\epsilon}_t^{(a)}-\mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\epsilon}_{t-1}^{(p)}\right)\bigg|\boldsymbol{\eta}_{t-1}\right]=\boldsymbol{0}.
\end{equation*}
Further, by the optimality (\ref{definition w*}),
\begin{equation*}
    \mathbb{E}\left[\gamma{\mathcal{Q}_d(\mathbf{X}_t)}^\top \boldsymbol{\xi}_t\bigg|\boldsymbol{\eta}_{t-1}\right]=\mathbb{E}\left[\gamma{\mathcal{Q}_d(\mathbf{X}_t)}^\top \left[\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_d(\mathbf{X}_t){\mathbf{w}^{(q)}}^*\right]\bigg|\boldsymbol{\eta}_{t-1}\right]=\boldsymbol{0}.
\end{equation*}
Hence, by Lemma \ref{update rule for eta_t},
\begin{equation}
    \label{conditional update}
    \mathbb{E}\left[\boldsymbol{\eta}_t|\boldsymbol{\eta}_{t-1}\right]=\left(\mathbf{I}-\gamma \mathbf{H}^{(q)}\right)\boldsymbol{\eta}_{t-1}.
\end{equation}
Therefore, by (\ref{D0}) and (\ref{conditional update}),
\begin{equation}
\label{etaN etaN}
    \begin{aligned}
        & \mathbb{E}[\overline{\boldsymbol{\eta}}_{N}\otimes\overline{\boldsymbol{\eta}}_{N}] \\
        \preceq &\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_k]\right]+\sum_{0\leq t\leq k\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_t]\right]\right)\\
        =&\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{t-k}\mathbb{E}[\boldsymbol{\eta}_k\otimes\boldsymbol{\eta}_k]+\sum_{0\leq t\leq k\leq N-1}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t](\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\right) \\
        =&\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left((\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t]+\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t](\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\right).
    \end{aligned}
\end{equation}
Applying (\ref{etaN etaN}) into $R_N^{(0)}$, we have
\begin{equation*}
    \begin{aligned}
        R_N^{(0)}=&\frac{1}{2}\langle\mathbf{H}^{(q)},\mathbb{E}[\overline{\boldsymbol{\eta}}_N\otimes\overline{\boldsymbol{\eta}}_N]\rangle\\
        \leq&\frac{1}{2N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle\mathbf{H}^{(q)},(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t]+\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t](\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\right\rangle \\
        =&\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t]\right\rangle,
    \end{aligned}
\end{equation*}
where the last equality holds since $\mathbf{H}^{(q)}$ and $(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}$ commute. This completes the proof.

\begin{equation}
    \label{D0}
        \begin{aligned}
            \mathbb{E}[\overline{\boldsymbol{\eta}}_{N}\otimes\overline{\boldsymbol{\eta}}_{N}]
            =&\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k]+\sum_{0\leq t<k\leq N-1}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k]\right) \\
            \preceq&\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_k]\right]+\sum_{0\leq t\leq k\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_t]\right]\right).
        \end{aligned}
    \end{equation}

\begin{equation}
    \label{etaN etaN}
        \begin{aligned}
            & \mathbb{E}[\overline{\boldsymbol{\eta}}_{N}\otimes\overline{\boldsymbol{\eta}}_{N}] \\
            \preceq &\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_k]\right]+\sum_{0\leq t\leq k\leq N-1}\mathbb{E}\left[\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_k|\boldsymbol{\eta}_t]\right]\right)\\
            =&\frac{1}{N^2}\cdot\left(\sum_{0\leq k\leq t\leq N-1}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{t-k}\mathbb{E}[\boldsymbol{\eta}_k\otimes\boldsymbol{\eta}_k]+\sum_{0\leq t\leq k\leq N-1}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t](\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\right) \\
            =&\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left((\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t]+\mathbb{E}[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t](\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\right).
        \end{aligned}
    \end{equation}

\label{update rule for eta_t^2}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3},
\begin{gather*}
        \mathbf{C}_t
        \preceq \mathbb{E}\left[\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]+\gamma^2 {\sigma_G^{(q)}}^2\mathbf{H}^{(q)},\\
        \mathbf{B}_t
        = \mathbb{E}\left[\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{B}_{t-1}\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right],
\end{gather*}
where
\begin{equation*}
    \begin{aligned}
        {\sigma_G^{(q)}}^2=&\frac{\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}\\
        +&\alpha_B\sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]
    +\frac{\sigma^2}{B},
    \end{aligned}
\end{equation*}
with $\mathbf{a}_t=\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1}),\ \mathbf{o}_t=\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_a\left(\mathcal{Q}_d(\mathbf{X}_t)\mathcal{Q}_p(\mathbf{w}_{t-1})\right)$ and $\|\cdot\|$ denoting the spectral norm.

We cope with each term in $\boldsymbol{\Sigma}_t$ to provide an upper bound. For $\boldsymbol{\Sigma}_t^{\epsilon^{(p)}}$,
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\Sigma}_t^{\epsilon^{(p)}}=&\frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top {\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right]\\

        \preceq &\alpha_B \sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]\mathbf{H}^{(q)},
    \end{aligned}
\end{equation*}
where the inequality holds by Assumption \ref{ass2}. For $\boldsymbol{\Sigma}_t^\xi$,
\begin{equation}
\label{Sigma epsilon t}
    \begin{aligned}
        \boldsymbol{\Sigma}_t^\xi=&\frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \boldsymbol{\xi}_t\boldsymbol{\xi}_t^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        =&\frac{1}{B^2}\mathbb{E}\left[\sum_{i=1}^B\sum_{j=1}^B {{\mathcal{Q}_d(\mathbf{X}_t)}^i}^\top \boldsymbol{\xi}_t^i \left({{\mathcal{Q}_d(\mathbf{X}_t)}^j}^\top \boldsymbol{\xi}_t^j\right)^\top\right]\\
        =&\frac{1}{B^2}\sum_{i=1}^B\mathbb{E}\left[{{\mathcal{Q}_d(\mathbf{X}_t)}^i}^\top \boldsymbol{\xi}_t^i \left({{\mathcal{Q}_d(\mathbf{X}_t)}^i}^\top \boldsymbol{\xi}_t^i\right)^\top\right]\\
        =&\frac{1}{B}\cdot\mathbb{E}\left[{{\mathcal{Q}_d(\mathbf{x})}} \xi \left({{\mathcal{Q}_d(\mathbf{x}}}) \xi\right)^\top\right]\\
        =&\frac{1}{B}\cdot\mathbb{E}\left[\xi^2\mathcal{Q}_d(\mathbf{x})\mathcal{Q}_d(\mathbf{x})^\top\right]\\
        \preceq&\frac{\sigma^2}{B}\cdot\mathbf{H}^{(q)},
    \end{aligned}
\end{equation}
where the third equality holds as samples are independent and data quantization is applied to each sample independently, the inequality holds by Assumption \ref{ass3}. For $\boldsymbol{\Sigma}_t^{\epsilon^{(o)}}+\boldsymbol{\Sigma}_t^{\epsilon^{(a)}}$,
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\Sigma}_t^{\epsilon^{(o)}}+\boldsymbol{\Sigma}_t^{\epsilon^{(a)}}=&\frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top (\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top+\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top) \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        =&\frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \left(\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right] +\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right)\mathcal{Q}_d(\mathbf{X}_t)\right]\\
        \preceq &\frac{1}{B^2}\mathbb{E}\left[\left(\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right] +\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right){\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        \preceq & \frac{1}{B^2}\sup_t \left[\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right] \mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        =&\frac{1}{B}\sup_t \left[\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right] \mathbf{H}^{(q)},
    \end{aligned}
\end{equation*}
where $\|\cdot\|$ represents the matrix spectral norm.

Combining the upper bounds for $\boldsymbol{\Sigma}_t^{\epsilon^{(p)}}$, $\boldsymbol{\Sigma}_t^\xi$, $\boldsymbol{\Sigma}_t^{\epsilon^{(o)}}+\boldsymbol{\Sigma}_t^{\epsilon^{(a)}}$, (\ref{eq: bt}) and (\ref{eq: ct}) immediately completes the proof.

\label{update rule for eta_t^2 multiplicative}
If there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, it holds
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_t
        \preceq&\mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]\\
        +&\tilde{\epsilon}\mathbb{E}\left[\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top {\mathcal{Q}_d(\mathbf{X})}(\mathbf{B}_{t-1}+\mathbf{C}_{t-1})\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top\mathcal{Q}_d(\mathbf{X})\right]
        +\gamma^2 {\sigma_M^{(q)}}^2\mathbf{H}^{(q)},\\
        \mathbf{B}_t=& \mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{B}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right],
    \end{aligned}
\end{equation*}
where
\begin{gather*}
        \tilde{\epsilon}=8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+4\epsilon_p+4\epsilon_a(1+\epsilon_p),\\
        {\sigma_M^{(q)}}^2=\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right).
\end{gather*}

To complete the proof, we merely need to derive the upper bound for $\boldsymbol{\Sigma}_t=\boldsymbol{\Sigma}_t^\xi+\boldsymbol{\Sigma}_t^{\epsilon^{(a)}}+\boldsymbol{\Sigma}_t^{\epsilon^{(o)}}+\boldsymbol{\Sigma}_t^{\epsilon^{(p)}}$. Regarding $\boldsymbol{\Sigma}_t^\xi$, by the computation in the proof of Lemma \ref{update rule for eta_t^2}, i.e., (\ref{Sigma epsilon t}),
\begin{equation}
    \label{sigma xi t}\boldsymbol{\Sigma}_t^\xi\preceq \frac{\sigma^2}{B}\mathbf{H}^{(q)}.
\end{equation}
Regarding $\boldsymbol{\Sigma}_t^{\epsilon^{(p)}}$,
\begin{equation}
\label{bound for sigma tp}
    \begin{aligned}
        \boldsymbol{\Sigma}_t^{\epsilon^{(p)}}=&\frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]{\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right]\\
        =&\frac{\epsilon_p}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\mathbf{w}_{t-1}\mathbf{w}_{t-1}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right]\\
        \preceq &\frac{2\epsilon_p}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\boldsymbol{\eta}_{t-1}{\boldsymbol{\eta}_{t-1}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right]\\
        +&\frac{2\epsilon_p}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right].
    \end{aligned}
\end{equation}
Regarding $\boldsymbol{\Sigma}_t^{\epsilon^{(a)}}$, 
\begin{equation}
\label{sigma a t mul}
    \begin{aligned}
        \boldsymbol{\Sigma}_t^{\epsilon^{(a)}}=&\frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        =&\frac{\epsilon_a}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\mathbf{w}_{t-1}^{(q)}{\mathbf{w}_{t-1}^{(q)}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        =&\frac{(1+\epsilon_p)\epsilon_a}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\mathbf{w}_{t-1}{\mathbf{w}_{t-1}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        \preceq &\frac{2(1+\epsilon_p)\epsilon_a}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\boldsymbol{\eta}_{t-1}{\boldsymbol{\eta}_{t-1}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        +&\frac{2(1+\epsilon_p)\epsilon_a}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t){\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right].
    \end{aligned}
\end{equation}
Regarding $\boldsymbol{\Sigma}_t^{\epsilon^{(o)}}$,
similar to $\boldsymbol{\Sigma}_t^{\epsilon^{(a)}}$, it holds
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\Sigma}_t^{\epsilon^{(o)}}=&\frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        =&\frac{\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathbf{o}_t{\mathbf{o}_t}^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        \preceq&\frac{2\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_l(\mathbf{y}_t)\mathcal{Q}_l(\mathbf{y}_t)^\top \mathcal{Q}_d(\mathbf{X}_t)\right]
        +\frac{2\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_a(\mathbf{a}_t)\mathcal{Q}_a(\mathbf{a}_t)^\top \mathcal{Q}_d(\mathbf{X}_t)\right].
    \end{aligned}
\end{equation*}
For the second term,
\begin{equation*}
    \begin{aligned}
        &\frac{2\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_a(\mathbf{a}_t)\mathcal{Q}_a(\mathbf{a}_t)^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        \preceq&\frac{2(1+\epsilon_a)\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathbf{a}_t\mathbf{a}_t^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        \preceq&\frac{4(1+\epsilon_p)(1+\epsilon_a)\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\boldsymbol{\eta}_{t-1}{\boldsymbol{\eta}_{t-1}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        +&\frac{4(1+\epsilon_p)(1+\epsilon_a)\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)} {\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\right].
    \end{aligned}
\end{equation*}
For the first term,
\begin{equation*}
    \begin{aligned}
        \frac{2\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_l(\mathbf{y}_t)\mathcal{Q}_l(\mathbf{y}_t)^\top \mathcal{Q}_d(\mathbf{X}_t)\right]
        \preceq &\frac{4\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \boldsymbol{\xi}_t\boldsymbol{\xi}_t^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        +&\frac{4\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)} {\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\right],
    \end{aligned}
\end{equation*}
where we use $\boldsymbol{\xi}_t=\mathcal{Q}_l(\mathbf{y}_t)-\mathcal{Q}_d(\mathbf{X}_t)\mathbf{w}^{(q)^*}$. 
Further, by the bound for $\boldsymbol{\Sigma}_t^\xi$ (\ref{Sigma epsilon t}), we have
\begin{equation*}
    \frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top \boldsymbol{\xi}_{t}{\boldsymbol{\xi}_{t}}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\preceq \frac{\sigma^2}{B}\mathbf{H}^{(q)},
\end{equation*}
it follows that
\begin{equation}
\label{sigma o t mul}
    \begin{aligned}
        \boldsymbol{\Sigma}_t^{\epsilon^{(o)}} \preceq &\frac{4\epsilon_o\sigma^2}{B}\mathbf{H}^{(q)}+\frac{4(1+\epsilon_p)(1+\epsilon_a)\epsilon_o}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\boldsymbol{\eta}_{t-1}{\boldsymbol{\eta}_{t-1}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top  \mathcal{Q}_d(\mathbf{X}_t)\right]\\
        +&\frac{4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)} {\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\right].
    \end{aligned}
\end{equation}

Further, by Assumption \ref{ass2}, it holds
\begin{equation*}
    \frac{1}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)} {\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\right]\preceq \alpha_B\mathrm{tr}\left(\mathbf{H}^{(q)}{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top\right)\mathbf{H}^{(q)},
\end{equation*}
then together with (\ref{sigma xi t}), (\ref{bound for sigma tp}), (\ref{sigma a t mul}) and (\ref{sigma o t mul}) it holds
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\Sigma}_t \preceq& \frac{(1+4\epsilon_o)\sigma^2}{B}\mathbf{H}^{(q)} + \alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right)\mathrm{tr}\left(\mathbf{H}^{(q)}{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \right)\mathbf{H}^{(q)}\\
        +&\frac{4\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+2\epsilon_p+2\epsilon_a(1+\epsilon_p)}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\boldsymbol{\eta}_{t-1}{\boldsymbol{\eta}_{t-1}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right].
    \end{aligned}
\end{equation*}
Note that by the definition of multiplicative quantization,
\begin{equation*}
    \begin{aligned}
        \mathrm{tr}\left(\mathbf{H}^{(q)}{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \right)=\frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d},
    \end{aligned}
\end{equation*}
then
\begin{equation}
\label{sigma t mul}
    \begin{aligned}
        \boldsymbol{\Sigma}_t \preceq& \left[\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right)\right]\mathbf{H}^{(q)}\\
        +&\frac{4\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+2\epsilon_p+2\epsilon_a(1+\epsilon_p)}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\boldsymbol{\eta}_{t-1}{\boldsymbol{\eta}_{t-1}}^\top{\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right].
    \end{aligned}
\end{equation}
Hence, by (\ref{sigma t mul}), (\ref{eq: ct}) and $\mathbb{E}\left[\boldsymbol{\eta}_t\otimes\boldsymbol{\eta}_t\right] \preceq 2(\mathbf{B}_t+\mathbf{C}_t)$, we have
\begin{equation*}
    \begin{aligned}
        &\mathbf{C}_t\preceq\mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]\\
        +&\left[8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+4\epsilon_p+4\epsilon_a(1+\epsilon_p)\right]\mathbb{E}\left[\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top {\mathcal{Q}_d(\mathbf{X})}(\mathbf{B}_{t-1}+\mathbf{C}_{t-1})\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top\mathcal{Q}_d(\mathbf{X})\right]\\
        +&\gamma^2 \left[\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right)\right]\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

\label{Bias-Variance Decomposition under General Quantization}
    Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3},
    \begin{equation*}
        R_N^{(0)}/2\leq \underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{B}_t\right\rangle}_{\mathrm{bias}}+\underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{C}_t\right\rangle}_{\mathrm{variance}},
    \end{equation*}
    where
    \begin{equation*}
        \mathbf{B}_t:=(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^t \circ \mathbf{B}_0, \quad \mathbf{B}_0=\mathbb{E}\left[\boldsymbol{\eta}_0 \otimes \boldsymbol{\eta}_0\right].
    \end{equation*}
    \begin{equation*}
        \mathbf{C}_t := (\mathcal{I}-\gamma \mathcal{T}_B^{(q)})\circ\mathbf{C}_{t-1}+\gamma^2 {\sigma_G^{(q)}}^2\mathbf{H}^{(q)},\quad \mathbf{C}_0=\boldsymbol{0}.
    \end{equation*}

By Lemma \ref{Initial study of R_2},
\begin{equation*}
    \begin{aligned}
        R_N^{(0)}\leq &\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbb{E}[\boldsymbol{\eta}_t\otimes \boldsymbol{\eta}_t]\right\rangle.
    \end{aligned}
\end{equation*}
The proof is immediately completed by Lemma \ref{update rule for eta_t^2} and $\mathbb{E}[\boldsymbol{\eta}_t\otimes \boldsymbol{\eta}_t]\preceq 2(\mathbf{B}_t+\mathbf{C}_t).$

\label{Bias-Variance Decomposition under Multiplicative Quantization}
    Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
    \begin{equation*}
        R_N^{(0)}/2\leq \underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{B}_t^{(M)}\right\rangle}_{\mathrm{bias}}+\underbrace{\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{C}_t^{(M)}\right\rangle}_{\mathrm{variance}},
    \end{equation*}
    where
    \begin{equation*}
        \mathbf{B}_t^{(M)}:=(\mathcal{I}-\gamma\mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^t \circ \mathbf{B}_0^{(M)}, \quad \mathbf{B}_0^{(M)}=\mathbb{E}\left[\boldsymbol{\eta}_0 \otimes \boldsymbol{\eta}_0\right].
    \end{equation*}
    \begin{equation*}
        \mathbf{C}_t^{(M)}: = (\mathcal{I}-\gamma \mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})\circ\mathbf{C}_{t-1}^{(M)}+\gamma^2 {\sigma_M^{(q)}}^2\mathbf{H}^{(q)}, \quad \mathbf{C}_0^{(M)}=0.
    \end{equation*}

By Lemma \ref{update rule for eta_t^2 multiplicative},
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_t
        \preceq&\mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]\\
        +&\tilde{\epsilon}\mathbb{E}\left[\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top {\mathcal{Q}_d(\mathbf{X})}(\mathbf{B}_{t-1}+\mathbf{C}_{t-1})\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top\mathcal{Q}_d(\mathbf{X})\right]
        +\gamma^2 {\sigma_M^{(q)}}^2\mathbf{H}^{(q)},\\
        \mathbf{B}_t=& \mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{B}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right].
    \end{aligned}
\end{equation*}
Hence,
\begin{equation*}
    \begin{aligned}
        \mathbb{E}\left[\boldsymbol{\eta}_t \otimes \boldsymbol{\eta}_t\right] \preceq &2(\mathbf{B}_t+\mathbf{C}_t)\\
        \preceq&2\left[(\mathcal{I}-\gamma \mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})\circ\left(\mathbf{B}_{t-1}+\mathbf{C}_{t-1}\right)+\gamma^2 {\sigma_M^{(q)}}^2\mathbf{H}^{(q)}\right]\\
        \preceq&2\left(\mathbf{B}_t^{(M)}+\mathbf{C}_t^{(M)}\right).
    \end{aligned}
\end{equation*}
Applying Lemma \ref{Initial study of R_2} completes the proof.

By definition,
\begin{equation}
    \label{22222}
    \begin{aligned}
        \mathbf{S}_t=&\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^k\circ\mathbf{B}_0\\
        =&(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})\circ\left(\sum_{k=1}^{t-1}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^{k-1}\circ\mathbf{B}_0\right)+\mathbf{B}_0\\
        =&(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})\circ\mathbf{S}_{t-1}+\mathbf{B}_0.
    \end{aligned}
\end{equation}
Then we convert $\mathcal{T}_B^{(q)}$ to $\widetilde{\mathcal{T}}^{(q)}$. By (\ref{22222}),
\begin{equation*}
    \begin{aligned}
        \mathbf{S}_{t} =& (\mathcal{I}-\gamma\mathcal{T}_B^{(q)})\circ\mathbf{S}_{t-1}+\mathbf{B}_0\\
        =& (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+\gamma (\widetilde{\mathcal{T}}^{(q)}-{\mathcal{T}}_B^{(q)})\circ\mathbf{S}_{t-1}+\mathbf{B}_0\\
        =& (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+\gamma^2 ({\mathcal{M}}_B^{(q)}-\widetilde{\mathcal{M}}^{(q)})\circ\mathbf{S}_{t-1}+\mathbf{B}_0\\
        \preceq&(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+\gamma^{2}\mathcal{M}_B^{(q)}\circ\mathbf{S}_{N}+\mathbf{B}_{0},
    \end{aligned}
\end{equation*}
where the third equality holds by the definition of linear operators.

\label{(Initial Study of $S_t$) mu}
    For $1 \leq t\leq N$,
    \begin{equation*}           
        \mathbf{S}_{t}^{(M)}\preceq(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+(1+\tilde{\epsilon})\gamma^{2}\mathcal{M}_B^{(q)}\circ\mathbf{S}_{N}^{(M)}+\mathbf{B}_{0}.
    \end{equation*}

The proof is similar to the proof for Lemma \ref{(Initial Study of $S_t$)}.
\begin{equation*}
    \begin{aligned}
        \mathbf{S}_{t}^{(M)} =& (\mathcal{I}-\gamma\mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+\mathbf{B}_0\\
        =& (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+\gamma (\widetilde{\mathcal{T}}^{(q)}-{\mathcal{T}}_B^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)}\circ \mathbf{S}_{t-1}^{(M)}+\mathbf{B}_0\\
        =& (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+\gamma^2 ((1+\tilde{\epsilon}){\mathcal{M}}_B^{(q)}-\widetilde{\mathcal{M}}^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+\mathbf{B}_0\\
        \preceq&(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+(1+\tilde{\epsilon})\gamma^{2}\mathcal{M}_B^{(q)}\circ\mathbf{S}_{N}^{(M)}+\mathbf{B}_{0}.
    \end{aligned}
\end{equation*}

For $1 \leq t\leq N$, under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\label{A bound for M_B^{(q)} S_t}
\begin{equation*}
     \mathcal{M}_B^{(q)} \circ \mathbf{S}_t \preceq \frac{\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t\right]\circ\mathbf{B}_0\right)}{\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}.
\end{equation*}

We prove by deriving a crude bound for $\mathbf{S}_t$ and applying $\mathcal{M}_B^{(q)}$ to this crude bound. Take summation via the update rule, we have
\begin{equation*}
    \mathbf{S}_{t} =\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^k\circ\mathbf{B}_0=\gamma^{-1}{\mathcal{T}^{(q)}_B}^{-1}\circ\left[\mathcal{I}-(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^t\right]\circ\mathbf{B}_0.
\end{equation*}
Note that
\begin{equation*}
    \mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)} \preceq \mathcal{I}-\gamma\mathcal{T}_B^{(q)}, \quad (\mathcal{I}-(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^t) \preceq (\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t),
\end{equation*}
and further note that ${\mathcal{T}_B^{(q)}}^{-1}$ is a PSD mapping \footnote{${\mathcal{T}_B^{(q)}}^{-1}$ is a PSD mapping under the condition that $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, which can be directly deduced by Lemma B.1 in \citet{zou2023benign}. We omit the proof here for simplicity.}, and $[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t]\circ\mathbf{B}_0$ is a PSD matrix, we obtain
\begin{equation*}
    \mathbf{S}_t\preceq\gamma^{-1}{\mathcal{T}_B^{(q)}}^{-1}\circ(\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t)\circ\mathbf{B}_0.
\end{equation*}
For simplicity, we denote $\mathbf{A}:=(\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t)\circ\mathbf{B}_0$. We then tackle ${\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A}$. To be specific, we apply $\widetilde{\mathcal{T}}^{(q)}$.
\begin{equation*}
    \begin{aligned}
        \widetilde{\mathcal{T}}^{(q)}\circ{\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A}\preceq \gamma\mathcal{M}_B^{(q)}\circ{\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A}+\mathbf{A}.
    \end{aligned}
\end{equation*}
Therefore,
\begin{equation*}
    \begin{aligned}
        {\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A} \preceq \gamma{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathcal{M}_B^{(q)}\circ{\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A}+(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{A}.
    \end{aligned}
\end{equation*}

Then we apply $\mathcal{M}_B^{(q)}$ on both sides.
\begin{equation}
    \begin{aligned}
    \label{11111}
        \mathcal{M}_B^{(q)} \circ ({\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A}) &\preceq \mathcal{M}_B^{(q)} \circ\gamma{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathcal{M}_B^{(q)}\circ{\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A}+ \mathcal{M}_B^{(q)} \circ(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{A}\\
        &\preceq\sum_{t=0}^\infty(\gamma\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1})^t\circ(\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A}) \ \text{(By recursion)}.
    \end{aligned}
\end{equation}
By Assumption \ref{ass2}, 
\begin{equation*}
    \begin{aligned}
        {\mathcal{M}_B^{(q)}}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A}&\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A})\mathbf{H}^{(q)}\\
        &= \alpha_B \gamma\operatorname{tr}\left(\sum_{t=0}^{\infty}\mathbf{H}^{(q)}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{t}\mathbf{A}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{t}\right) \mathbf{H}^{(q)}\\
        &= \alpha_B \mathrm{tr}\left(\mathbf{H}^{(q)}(2\mathbf{H}^{(q)}-\gamma(\mathbf{H}^{(q)})^{2})^{-1}\mathbf{A}\right)\mathbf{H}^{(q)}\\
        &\preceq \alpha_B \mathrm{tr}(\mathbf{A})\mathbf{H}^{(q)},
    \end{aligned}
\end{equation*}
where the first equality holds by the definition of $\widetilde{\mathcal{T}}^{(q)}$ and the last inequality requires the condition that $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$. Hence, by (\ref{11111}), and further by ${(\widetilde{\mathcal{T}}^{(q)})}^{-1}\mathbf{H}^{(q)}\preceq\mathbf{I}$ and $\mathcal{M}_B^{(q)}\circ\mathbf{I}\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}$, we obtain
\begin{equation*}
    \begin{aligned}
        \mathcal{M}_B^{(q)} \circ ({\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{A}) &\preceq\sum_{t=0}^\infty(\gamma\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1})^t\circ(\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A})\\
        &\preceq\alpha_B\operatorname{tr}(\mathbf{A})\sum_{t=0}^{\infty}(\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))^t\mathbf{H}^{(q)}\\
        &\preceq\frac{\alpha_B\operatorname{tr}(\mathbf{A})}{1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}
Therefore,
\begin{equation*}
    \begin{aligned}
        \mathcal{M}_B^{(q)} \circ \mathbf{S}_t \preceq \gamma^{-1}\frac{\alpha_B\operatorname{tr}(\mathbf{A})}{1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}=\frac{\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t\right]\circ\mathbf{B}_0\right)}{\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

\label{A bound for M_B^{(q)} S_t^{(M)}}
For $1 \leq t\leq N$, under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$,
\begin{equation*}
     \mathcal{M}_B^{(q)} \circ \mathbf{S}_t^{(M)} \preceq \frac{\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t\right]\circ\mathbf{B}_0\right)}{\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}.
\end{equation*}

The first step is to derive a crude bound for $\mathbf{S}_t^{(M)}$. Take summation via the update rule, we have \footnote{$({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}$ is a PSD mapping under the condition that $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, which can be directly deduced by Lemma B.1 in \citet{zou2023benign}. We omit the proof here for simplicity.}
\begin{equation*}
    \mathbf{S}_t^{(M)}=\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^k\circ\mathbf{B}_0=\gamma^{-1}({\mathcal{T}^{(q)}_B}-\tilde{\epsilon}\gamma\mathcal{M}_B^{(q)})^{-1}\circ\left[\mathcal{I}-(\mathcal{I}-\gamma\mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^t\right]\circ\mathbf{B}_0.
\end{equation*}
Note that
\begin{equation*}
    \mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)} \preceq \mathcal{I}-\gamma\mathcal{T}_B^{(q)}, \quad (\mathcal{I}-(\mathcal{I}-\gamma\mathcal{T}_B^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^t) \preceq (\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^t),
\end{equation*}
we obtain
\begin{equation*}
    \mathbf{S}_t^{(M)}\preceq\gamma^{-1}({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}\circ(\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^t)\circ\mathbf{B}_0.
\end{equation*}
Denote $\mathbf{A}:=(\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)}+\tilde{\epsilon}\gamma^2\mathcal{M}_B^{(q)})^t)\circ\mathbf{B}_0$, then applying $\widetilde{\mathcal{T}}^{(q)}$
\begin{equation*}
    \begin{aligned}
        \widetilde{\mathcal{T}}^{(q)}\circ({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}\circ\mathbf{A}&\preceq(1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}\circ\mathbf{A}+\mathbf{A}.
    \end{aligned}
\end{equation*}
Therefore
\begin{equation*}
    \begin{aligned}
        ({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}\circ\mathbf{A} \preceq (1+\tilde{\epsilon})\gamma{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathcal{M}_B^{(q)}\circ({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}\circ\mathbf{A}+(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{A}.
    \end{aligned}
\end{equation*}

Then we undertake the second step, applying $\mathcal{M}_B^{(q)}$ on both sides.
\begin{equation}
    \label{11111 M}
    \mathcal{M}_B^{(q)} \circ({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}\circ\mathbf{A}\preceq\sum_{t=0}^\infty((1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1})^t\circ(\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A}).
\end{equation}
By Assumption \ref{ass2}, 
\begin{equation}
\label{d16}
    \begin{aligned}
        {\mathcal{M}_B^{(q)}}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A}&\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A})\mathbf{H}^{(q)}\\
        &= \alpha_B \gamma\operatorname{tr}\left(\sum_{t=0}^{\infty}\mathbf{H}^{(q)}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{t}\mathbf{A}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{t}\right) \mathbf{H}^{(q)}\\
        &= \alpha_B \mathrm{tr}\left(\mathbf{H}^{(q)}(2\mathbf{H}^{(q)}-\gamma(\mathbf{H}^{(q)})^{2})^{-1}\mathbf{A}\right)\mathbf{H}^{(q)}\\
        &\preceq \alpha_B \mathrm{tr}(\mathbf{A})\mathbf{H}^{(q)},
    \end{aligned}
\end{equation}
where the last inequality requires the condition that $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$.
Hence, by (\ref{11111 M}), (\ref{d16}), and further by ${(\widetilde{\mathcal{T}}^{(q)})}^{-1}\mathbf{H}^{(q)}\preceq\mathbf{I}$ and $\mathcal{M}_B^{(q)}\circ\mathbf{I}\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}$, we obtain
\begin{equation*}
    \begin{aligned}
        \mathcal{M}_B^{(q)} \circ (({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}\circ\mathbf{A}) &\preceq\sum_{t=0}^\infty((1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1})^t\circ(\mathcal{M}_B^{(q)}\circ{(\widetilde{\mathcal{T}}^{(q)})}^{-1}\circ\mathbf{A})\\
        &\preceq\alpha_B\operatorname{tr}(\mathbf{A})\sum_{t=0}^{\infty}((1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))^t\mathbf{H}^{(q)}\\
        &\preceq\frac{\alpha_B\operatorname{tr}(\mathbf{A})}{1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}
Therefore,
\begin{equation*}
    \begin{aligned}
        \mathcal{M}_B^{(q)} \circ \mathbf{S}_t^{(M)} \preceq \gamma^{-1}\frac{\alpha_B\operatorname{tr}(\mathbf{A})}{1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}\preceq \frac{\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t\right]\circ\mathbf{B}_0\right)}{\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

\label{bias R2 bound}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\begin{equation*}
    \begin{aligned}
        \mathrm{bias}
        \leq & \frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

Recalling Lemma \ref{(Initial Study of $S_t$)}, we can derive a refined upper bound for $\mathbf{S}_t$ by Lemma \ref{A bound for M_B^{(q)} S_t}:
\begin{equation}
\label{Bound for S_t}
    \begin{aligned}
        \mathbf{S}_t\preceq&(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+\gamma^{2}\mathcal{M}_B^{(q)}\circ\mathbf{S}_{N}+\mathbf{B}_{0}\\
        \preceq&(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+\frac{\gamma\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^N\right]\circ\mathbf{B}_0\right)}{(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\\
        \preceq&\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})^k\left(\frac{\gamma\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^N\right]\circ\mathbf{B}_0\right)}{(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)\\
        =&\sum_{k=0}^{t-1}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k\left(\frac{\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_0-(\mathbf{I}-\gamma \mathbf{H}^{(q)})^N\mathbf{B}_0(\mathbf{I}-\gamma \mathbf{H}^{(q)})^N\right)}{(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k.
    \end{aligned}
\end{equation}

Before providing our upper bound for the bias error, we denote \begin{equation*}
    \mathbf{B}_{a,b}:=\mathbf{B}_a-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{b-a}\mathbf{B}_a(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{b-a}.
\end{equation*}
Then by (\ref{bias express}) and (\ref{Bound for S_t}),
\begin{equation*}
    \begin{aligned}
        \mathrm{bias}\leq&\frac{1}{\gamma N^{2}}\langle\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N},\sum_{t=0}^{N-1}\mathbf{B}_{t}\rangle\\
        \leq&\frac{1}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N},(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k\left(\frac{\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k\right\rangle\\
        =&\frac{1}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{2k}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+2k},\left(\frac{\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)\right\rangle.
    \end{aligned}
\end{equation*}
Note that 
\begin{equation*}
    \begin{aligned}
        (\mathbf{I}-\gamma\mathbf{H}^{(q)})^{2k}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+2k} & =\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)^{k}\left(\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)^{k}-\left(\mathbf{I}-\gamma\mathbf{H}^{(q)}\right)^{N+k}\right) \\
        & \preceq(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+k},
    \end{aligned}
\end{equation*}
we obtain
\begin{equation*}
    \mathrm{bias}\leq\frac{1}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+k},\frac{\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right\rangle.
\end{equation*}

Therefore, it suffices to upper bound the following two terms
\begin{equation*}
    \begin{aligned}
        & I_{1}=\frac{\alpha_B\operatorname{tr}(\mathbf{B}_{0,N})}{N^2(1-\gamma\alpha\operatorname{tr}(\mathbf{H}^{(q)}))}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+k},\mathbf{H}^{(q)}\right\rangle, \\
        & I_{2}=\frac{1}{\gamma N^2}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+k},\mathbf{B}_0\right\rangle.
    \end{aligned}
\end{equation*}

Regarding $I_1$, since $\mathbf{H}^{(q)}$ and $\mathbf{I}-\gamma\mathbf{H}^{(q)}$ can be diagonalized simultaneously, 
\begin{equation*}
    \begin{aligned}
        I_{1}& =\frac{\alpha_B\operatorname{tr}(\mathbf{B}_{0,N})}{N^2(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\sum_{k=0}^{N-1}\sum_i\left[(1-\gamma\lambda_i^{(q)})^k-(1-\gamma\lambda_i^{(q)})^{N+k}\right]\lambda_i^{(q)}\\
        & =\frac{\alpha_B\operatorname{tr}(\mathbf{B}_{0,N})}{\gamma N^2(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\sum_i\left[1-(1-\gamma\lambda_i^{(q)})^N\right]^2 \\
        & \leq\frac{\alpha_B\operatorname{tr}(\mathbf{B}_{0,N})}{\gamma N^2(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\sum_i\min\left\{1,\gamma^2N^2(\lambda_i^{(q)})^2\right\}\\
        &\leq\frac{\alpha_B\operatorname{tr}(\mathbf{B}_{0,N})}{\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N^2}+\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right),
    \end{aligned}
\end{equation*}
where $k^*=\max\{k:\lambda_k^{(q)}\geq\frac{1}{N\gamma}\}$. Then we tackle $\mathrm{tr}(\mathbf{B}_{0,N})$.
\begin{equation}
\label{trB0N}
    \begin{aligned}
        \mathrm{tr}(\mathbf{B}_{0,N})&=\mathrm{tr}\left(\mathbf{B}_{0}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N}\mathbf{B}_{0}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N}\right)\\
        &=\sum_{i}\left(1-(1-\gamma\lambda_{i}^{(q)})^{2N}\right)\cdot\left(\langle\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*},\mathbf{v}_{i}^{(q)}\rangle\right)^{2}\\
        &\leq 2\sum_i\min\{1,N\gamma\lambda_i^{(q)}\}\left(\langle\mathbf{w}_0-{\mathbf{w}^{(q)}}^*,\mathbf{v}_i^{(q)}\rangle\right)^2\\
        &\leq 2\left(\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{I}_{0:k^{*}}}^{2}+N\gamma\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{H}_{k^{*}:\infty}}^{2}\right).
    \end{aligned}
\end{equation}
Hence,
\begin{equation*}
    I_1\leq\frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
\end{equation*}

Regarding $I_2$, decompose $\mathbf{H}^{(q)}=\mathbf{V}^{(q)}\mathbf{\Lambda}^{(q)}{\mathbf{V}^{(q)}}^\top$, then
\begin{equation*}
    I_2=\frac{1}{\gamma N^2}\sum_{k=0}^{N-1}\langle(\mathbf{I}-\gamma\mathbf{\Lambda}^{(q)})^k-(\mathbf{I}-\gamma\mathbf{\Lambda}^{(q)})^{N+k},{\mathbf{V}^{(q)}}^\top\mathbf{B}_0\mathbf{V}^{(q)}\rangle.
\end{equation*}
Note that $\mathbf{B}_0=\boldsymbol{\eta}_0\boldsymbol{\eta}_0^\top$, it can be shown that the diagonal entries of ${\mathbf{V}^{(q)}}^\top\mathbf{B}_0\mathbf{V}^{(q)}$ are $\omega_1^2,\dots$, where $\omega_i={\mathbf{v}_{i}^{(q)}}^{\top}\boldsymbol{\eta}_{0}={\mathbf{v}_{i}^{(q)}}^{\top}(\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*})$. Hence,
\begin{equation*}
    \begin{aligned}
        I_{2} & =\frac{1}{\gamma N^{2}}\sum_{k=0}^{N-1}\sum_{i}\left[(1-\gamma\lambda_{i}^{(q)})^{k}-(1-\gamma\lambda_{i}^{(q)})^{N+k}\right]\omega_{i}^{2} \\
        & =\frac{1}{\gamma^{2}N^{2}}\sum_{i}\frac{\omega_{i}^{2}}{\lambda_{i}^{(q)}}\left[1-(1-\gamma\lambda_{i}^{(q)})^{N}\right]^{2} \\
        & \leq\frac{1}{\gamma^{2}N^{2}}\sum_{i}\frac{\omega_{i}^{2}}{\lambda_{i}^{(q)}}\operatorname*{min}\left\{1,\gamma^{2}N^{2}(\lambda_{i}^{(q)})^{2}\right\} \\
        & \leq\frac{1}{\gamma^{2}N^{2}}\cdot\sum_{i\leq k^{*}}\frac{\omega_{i}^{2}}{\lambda_{i}^{(q)}}+\sum_{i>k^{*}}\lambda_{i}^{(q)}\omega_{i}^{2}\\
        &=\frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{{k^*}:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

In conclusion, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$,
\begin{equation*}
    \begin{aligned}
        \mathrm{bias}\leq& I_1+I_2\\
        \leq & \frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

\label{bias R2 bound multiplicative}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
\begin{equation*}
    \begin{aligned}
        \mathrm{bias}\leq & \frac{2(1+\tilde{\epsilon})\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

Recalling Lemma \ref{(Initial Study of $S_t$) mu}, we can derive an upper bound for $\mathbf{S}_t$ by Lemma \ref{A bound for M_B^{(q)} S_t^{(M)}}:
\begin{equation*}
    \begin{aligned}
        \mathbf{S}_{t}\preceq&(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+(1+\tilde{\epsilon})\gamma^{2}\mathcal{M}_B^{(q)}\circ\mathbf{S}_{N}+\mathbf{B}_{0}\\
        \preceq &(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})\circ\mathbf{S}_{t-1}+\frac{(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^N\right]\circ\mathbf{B}_0\right)}{(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\\
        \preceq&\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\tilde{\mathcal{T}}^{(q)})^k\left(\frac{(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^N\right]\circ\mathbf{B}_0\right)}{(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)\\
        =&\sum_{k=0}^{t-1}(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k \left(\frac{(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_0-(\mathbf{I}-\gamma \mathbf{H}^{(q)})^N\mathbf{B}_0(\mathbf{I}-\gamma \mathbf{H}^{(q)})^N\right)}{(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right) (\mathbf{I}-\gamma\mathbf{H}^{(q)})^k.
    \end{aligned}
\end{equation*}
Repeat the same computation in the proof of Lemma \ref{bias R2 bound}, we obtain
\begin{equation}
    \label{eq: c21}
    \mathrm{bias}\leq\frac{1}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+k},\frac{(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right\rangle.
\end{equation}
Therefore, it suffices to upper bound the following two terms
\begin{equation*}
    \begin{aligned}
        & I_{1}=\frac{(1+\tilde{\epsilon})\alpha_B\operatorname{tr}(\mathbf{B}_{0,N})}{N^2(1-(1+\tilde{\epsilon})\gamma\alpha\operatorname{tr}(\mathbf{H}^{(q)}))}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+k},\mathbf{H}^{(q)}\right\rangle, \\
        & I_{2}=\frac{1}{\gamma N^2}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^k-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N+k},\mathbf{B}_0\right\rangle.
    \end{aligned}
\end{equation*}

Repeating the computation in the proof of Lemma \ref{bias R2 bound},
\begin{equation*}
    I_1\leq\frac{2(1+\tilde{\epsilon})\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
\end{equation*}
\begin{equation*}
    I_2 \leq \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{{k^*}:\infty}^{(q)}}^2.
\end{equation*}

In conclusion, if the stepsize satisfies $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$,
\begin{equation*}
    \begin{aligned}
        \mathrm{bias}\leq & \frac{2(1+\tilde{\epsilon})\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

\label{A bound for M_B^{(q)} C_t}
For $t \geq 1$, under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize $\gamma \leq \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t \preceq \frac{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\gamma{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}.
\end{equation*}

The main goal is to derive a crude upper bound for $\mathbf{C}_t$. Denote $\boldsymbol{\Sigma}={\sigma_G^{(q)}}^2\mathbf{H}^{(q)}$.

\textbf{Step 1: $\mathbf{C}_t$ is increasing.} By definition,
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_{t} & =(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})\circ\mathbf{C}_{t-1}+\gamma^{2}\boldsymbol{\Sigma} \\
        & =\gamma^2\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^k\circ\boldsymbol{\Sigma}\quad\text{(solving the recursion)} \\
        & =\mathbf{C}_{t-1}+\gamma^{2}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^{t-1}\circ\mathbf{\Sigma} \\
        & \succeq\mathbf{C}_{t-1}.\quad(\mathrm{since~}\mathcal{I}-\gamma\mathcal{T}_B^{(q)}\text{ is a PSD mapping}).
    \end{aligned}
\end{equation*}

\textbf{Step 2: $\mathbf{C}_\infty$ exists.}
It suffices to show that $\mathrm{tr}(\mathbf{C}_t)$ is uniformly upper bounded. To be specific, for any $t\geq 1$,
\begin{equation*}
    \mathbf{C}_t=\gamma^2\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^k\circ\boldsymbol{\Sigma}\preceq\gamma^2\sum_{t=0}^\infty(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^t\circ\boldsymbol{\Sigma}.
\end{equation*}
Then
\begin{equation*}
    \mathrm{tr}(\mathbf{C}_t)\leq\gamma^2\sum_{t=0}^\infty\mathrm{tr}\left((\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^t\circ\boldsymbol{\Sigma}\right):=\gamma^2\sum_{t=0}^\infty\mathrm{tr}(\mathbf{E}_t)\leq\frac{\gamma\operatorname{tr}(\boldsymbol{\Sigma})}{\lambda_d^{(q)}}<\infty,
\end{equation*}
where the second inequality holds by the iteration:
\begin{equation*}
    \begin{aligned}
        \operatorname{tr}(\mathbf{E}_{t}) & =\mathrm{tr}(\mathbf{E}_{t-1})-2\gamma\mathrm{tr}(\mathbf{H}^{(q)}\mathbf{E}_{t-1})+\gamma^{2}\mathrm{tr}\left(\mathbf{E}_{t-1}\mathbb{E}\left[\frac{1}{B^2} {\mathbf{X}^{(q)}}^\top{\mathbf{X}^{(q)}}{\mathbf{X}^{(q)}}^\top{\mathbf{X}^{(q)}} \right]\right) \\
        & \leq\operatorname{tr}(\mathbf{E}_{t-1})-(2\gamma-\gamma^{2}\alpha_B\mathrm{tr}(\mathbf{H}^{(q)}))\operatorname{tr}(\mathbf{H}^{(q)}\mathbf{E}_{t-1}) \\
        & \leq\mathrm{tr}\left((\mathbf{I}-\gamma\mathbf{H}^{(q)})\mathbf{E}_{t-1}\right) \\
        & \leq(1-\gamma\lambda_{d}^{(q)})\operatorname{tr}(\mathbf{E}_{t-1}),
    \end{aligned}
\end{equation*} 
where the first inequality holds by Assumption \ref{ass2} and the second inequality holds if $\gamma \leq \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$.

\textbf{Step 3: upper bound $\mathbf{C}_\infty$.} By the update rule for $\mathbf{C}_t$,
\begin{equation*}
    \mathbf{C}_\infty=(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})\circ\mathbf{C}_\infty+\gamma^2\boldsymbol{\Sigma},
\end{equation*}
which immediately implies 
\begin{equation}
\label{solution of Cinfty}
    \mathbf{C}_\infty=\gamma{\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{\Sigma}.
\end{equation}
We provide the upper bound by applying $\widetilde{\mathcal{T}}^{(q)}$.
\begin{equation*}
    \begin{aligned}
        \widetilde{\mathcal{T}}^{(q)}\circ\mathbf{C}_{\infty} & =\mathcal{T}_B^{(q)}\circ\mathbf{C}_{\infty}+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_{\infty}-\gamma\widetilde{\mathcal{M}}^{(q)}\circ\mathbf{C}_{\infty} \\
        & =\gamma\boldsymbol{\Sigma}+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty-\gamma\widetilde{\mathcal{M}}^{(q)}\circ\mathbf{C}_\infty\\
        & \preceq\gamma\boldsymbol{\Sigma}+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty,
    \end{aligned}
\end{equation*}
where the first equality holds by the definition of $\mathcal{T}_B^{(q)}$ and $\widetilde{\mathcal{T}}^{(q)}$ and the second equality holds by (\ref{solution of Cinfty}).
Hence,
\begin{equation*}
    \widetilde{\mathcal{T}}^{(q)}\circ\mathbf{C}_{\infty}\preceq \gamma{\sigma_G^{(q)}}^2\mathbf{H}^{(q)}+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty.
\end{equation*}
Therefore, by applying $(\widetilde{\mathcal{T}}^{(q)})^{-1}$ we have
\begin{equation}
\label{202020}
    \begin{aligned}
        \mathbf{C}_{\infty} & \preceq\gamma{\sigma_G^{(q)}}^2\cdot(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}+\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty \\
        & \preceq\gamma{\sigma_G^{(q)}}^2\cdot\sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}.\quad\text{(solving the recursion)}
    \end{aligned}
\end{equation}
We first deal with $(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}$. 
\begin{equation}
\label{101010}
    \begin{aligned}
        (\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)} & =\gamma\sum_{t=0}^\infty(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t\circ\mathbf{H}^{(q)} \\
        & =\gamma\sum_{t=0}^\infty(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\mathbf{H}^{(q)}(\mathbf{I}- \gamma\mathbf{H}^{(q)})^t \\
        & \preceq\gamma\sum_{t=0}^\infty(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\mathbf{H}^{(q)} \\
        &= \mathbf{I},
    \end{aligned}
\end{equation}
where the second equality uses the definition of $\widetilde{\mathcal{T}}^{(q)}$.
Hence, by (\ref{202020}) and (\ref{101010}),
\begin{equation}
    \label{eq: c26}
    \begin{aligned}
        \mathbf{C}_{\infty} & \preceq\gamma{\sigma_G^{(q)}}^2\cdot\sum_{t=0}^\infty(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)})^t\circ\mathbf{I} \\
        &=\gamma{\sigma_G^{(q)}}^2\cdot\sum_{t=0}^\infty(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)})^{t-1}\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ\mathbf{I} \\
        &\preceq\gamma{\sigma_G^{(q)}}^2\cdot\sum_{t=0}^\infty(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)})^{t-1}\circ\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\mathbf{I} \\
        &\preceq\gamma{\sigma_G^{(q)}}^2\cdot\sum_{t=0}^\infty\left(\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\right)^{t}\mathbf{I} \\
        &= \frac{\gamma{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{I},
    \end{aligned}
\end{equation}
where the second inequality holds by the fact that $\mathcal{M}_B^{(q)}\circ\mathbf{I}\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}$. 

Here we complete deriving a crude upper bound for $\mathbf{C}_t$:
\begin{equation*}
    \mathbf{C}_t \preceq \mathbf{C}_\infty \preceq\frac{\gamma{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{I}.
\end{equation*}
Then by $\mathcal{M}_B^{(q)}\circ\mathbf{I}\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}$ again,
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t \preceq \frac{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\gamma{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}.
\end{equation*}

\begin{equation*}
        \begin{aligned}
            \mathbf{C}_{t} & =(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})\circ\mathbf{C}_{t-1}+\gamma^{2}\boldsymbol{\Sigma} \\
            & =\gamma^2\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^k\circ\boldsymbol{\Sigma}\quad\text{(solving the recursion)} \\
            & =\mathbf{C}_{t-1}+\gamma^{2}(\mathcal{I}-\gamma\mathcal{T}_B^{(q)})^{t-1}\circ\mathbf{\Sigma} \\
            & \succeq\mathbf{C}_{t-1}.\quad(\mathrm{since~}\mathcal{I}-\gamma\mathcal{T}_B^{(q)}\text{ is a PSD mapping}).
        \end{aligned}
    \end{equation*}

\label{A bound for M_B^{(q)} C_t^{(M)}}
For $t \geq 1$, under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize $\gamma \leq \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t^{(M)} \preceq \frac{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\gamma{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}.
\end{equation*}

The proof idea is similar to the proof of Lemma \ref{A bound for M_B^{(q)} C_t} while the main goal is to derive a crude upper bound for $\mathbf{C}_t^{(M)}$. We deduce from the proof of Lemma \ref{A bound for M_B^{(q)} C_t} that \footnote{$({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma \mathcal{M}_B^{(q)})^{-1}$ exists under the condition that $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, which can be directly deduced by Lemma B.1 in \citet{zou2023benign}. We omit the proof here for simplicity.}
\begin{equation}
\label{express CinftyM}
    \mathbf{C}_t^{(M)}\preceq \mathbf{C}_\infty^{(M)}=\gamma({\mathcal{T}_B^{(q)}}-\tilde{\epsilon}\gamma\mathcal{M}_B^{(q)})^{-1}\circ{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}.
\end{equation}

We provide the upper bound for $\mathbf{C}_\infty^{(M)}$ by applying $\widetilde{\mathcal{T}}^{(q)}$.
\begin{equation*}
    \begin{aligned}
        \widetilde{\mathcal{T}}^{(q)}\circ\mathbf{C}_\infty^{(M)} & =(\mathcal{T}_B^{(q)}-\tilde{\epsilon}\gamma\mathcal{M}_B^{(q)})\circ\mathbf{C}_\infty^{(M)}+(1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty^{(M)}-\gamma\widetilde{\mathcal{M}}^{(q)}\circ\mathbf{C}_\infty^{(M)} \\
        & =\gamma{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+(1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty^{(M)}-\gamma\widetilde{\mathcal{M}}^{(q)}\circ\mathbf{C}_\infty^{(M)}\\
        & \preceq\gamma{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+(1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty^{(M)},
    \end{aligned}
\end{equation*}
where the first equality holds by the definition of $\widetilde{\mathcal{T}}^{(q)}$ and the second equality holds by the definition of $\mathbf{C}_\infty^{(M)}$ (\ref{express CinftyM}).
Therefore, applying $(\widetilde{\mathcal{T}}^{(q)})^{-1}$ we have
\begin{equation}
\label{303030}
    \begin{aligned}
        \mathbf{C}_{\infty}^{(M)} & \preceq\gamma{\sigma_M^{(q)}}^2\cdot(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}+(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty^{(M)} \\
        & \preceq\gamma{\sigma_M^{(q)}}^2\cdot\sum_{t=0}^\infty((1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)})^t\circ(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}.\quad\text{(solving the recursion)}
    \end{aligned}
\end{equation}
By the computation (\ref{101010}) in the proof for Lemma \ref{A bound for M_B^{(q)} C_t},
\begin{equation}
\label{404040}
    \begin{aligned}
        (\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}  \preceq \mathbf{I}.
    \end{aligned}
\end{equation}
Hence, by (\ref{303030}) and (\ref{404040}),
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_{\infty}^{(M)} & \preceq\gamma{\sigma_M^{(q)}}^2\cdot\sum_{t=0}^\infty((1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)})^t\circ\mathbf{I} \\
        &=\gamma{\sigma_M^{(q)}}^2\cdot\sum_{t=0}^\infty((1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)})^{t-1}(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ\mathbf{I} \\
        &\preceq\gamma{\sigma_M^{(q)}}^2\cdot\sum_{t=0}^\infty((1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)})^{t-1}\circ(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\mathbf{I} \\
        &\preceq\gamma{\sigma_M^{(q)}}^2\cdot\sum_{t=0}^\infty\left((1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\right)^{t}\mathbf{I} \\
        &= \frac{\gamma{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{I},
    \end{aligned}
\end{equation*}
where the second inequality holds by the fact that $\mathcal{M}_B^{(q)}\circ\mathbf{I}\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}$.

Therefore, we complete the proof by
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t^{(M)} \preceq \frac{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\gamma{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}.
\end{equation*}

\label{variance R2 bound}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\begin{equation*}
    \begin{aligned}
        \mathrm{variance}\leq  \frac{{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
    \end{aligned}
\end{equation*}

We first provide a refined upper bound for $\mathbf{C}_t$. By (\ref{initial Ct}),
\begin{equation}
\label{bound for C_t}
    \begin{aligned}
        \mathbf{C}_t \preceq &(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1}+\gamma^2\mathcal{M}_B^{(q)}\circ \mathbf{C}_{t-1}+\gamma^2{\sigma_G^{(q)}}^2\mathbf{H}^{(q)}\\
        \preceq & (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1} + \frac{\gamma^2\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\gamma{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}+\gamma^2{\sigma_G^{(q)}}^2\mathbf{H}^{(q)}\\
        =& (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1} + \frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}\\
        \preceq&\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^k\circ\mathbf{H}^{(q)}\quad\text{(solving the recursion)} \\
        =&\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\sum_{k=0}^{t-1}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^k\mathbf{H}^{(q)}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^k \\
        \preceq&\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\sum_{k=0}^{t-1}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^k\mathbf{H}^{(q)} \\
        =&\frac{\gamma{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\right),
    \end{aligned}
\end{equation}
where the second inequality holds by Lemma \ref{A bound for M_B^{(q)} C_t} and the second equality holds by the definition of $\widetilde{\mathcal{T}}^{(q)}$.

After providing a refined bound for $\mathbf{C}_t$, we are ready to bound the variance. By Lemma \ref{Bias-Variance Decomposition under General Quantization},
\begin{equation}
    \label{eq: c31}
    \begin{aligned}
        \mathrm{variance}=&\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{C}_t\right\rangle\\
        =&\frac{1}{\gamma N^{2}}\sum_{t=0}^{N-1}\left\langle\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N-t},\mathbf{C}_{t}\right\rangle\\
        \leq&\frac{1}{\gamma^2 N^{2}}\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_{t=0}^{N-1}\left\langle\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N-t},\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\right\rangle\\
        =&\frac{1}{\gamma^2 N^{2}}\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_i\sum_{t=0}^{N-1}\left[1-(1-\gamma\lambda_i^{(q)})^{N-t}\right]\left[1-(1-\gamma\lambda_i^{(q)})^t\right]\\
        \leq&\frac{1}{\gamma^2 N^{2}}\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_i\sum_{t=0}^{N-1}\left[1-(1-\gamma\lambda_i^{(q)})^{N}\right]\left[1-(1-\gamma\lambda_i^{(q)})^N\right]\\
        =&\frac{1}{\gamma^2 N}\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_i\left[1-(1-\gamma\lambda_i^{(q)})^{N}\right]^2\\
        \leq &\frac{1}{\gamma^2 N}\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_i \min\left\{1,\gamma^2 N^2(\lambda_i^{(q)})^2\right\}\\
        \leq &\frac{1}{\gamma^2 N}\frac{\gamma^2{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(k^*+N^2\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        =&\frac{{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),
    \end{aligned}
\end{equation}
where the first inequality holds by (\ref{bound for C_t}) and the last inequality holds by the definition of $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$. This immediately completes the proof.

\label{variance R2 bound multipicative}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
\begin{equation*}
    \begin{aligned}
        \mathrm{variance}\leq  \frac{{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
    \end{aligned}
\end{equation*}

Applying (\ref{initial CtM}), and repeating the computation in the proof of Lemma \ref{variance R2 bound},
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_t^{(M)}\preceq&(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1}^{(M)}+\gamma^2(1+\tilde{\epsilon})\mathcal{M}_B^{(q)}\circ \mathbf{C}_{t-1}^{(M)}+\gamma^2{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}\\
        \preceq&(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1}^{(M)}+\gamma^2(1+\tilde{\epsilon})\frac{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\gamma{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}+\gamma^2{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}\\
        =&(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1}^{(M)}+\frac{\gamma^2{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}\\
        \preceq &\frac{\gamma{\sigma_M ^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\right),
    \end{aligned}
\end{equation*}
where the second inequality holds by Lemma \ref{A bound for M_B^{(q)} C_t^{(M)}} and the last inequality repeats the proof in (\ref{bound for C_t}).

Therefore, repeating the procedure in the proof for Lemma \ref{variance R2 bound}, we directly deduce that
\begin{equation*}
    \begin{aligned}
        \mathrm{variance}\leq  \frac{{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),
    \end{aligned}
\end{equation*}
which immediately completes the proof.

\label{R_2 bound}
    Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
    \begin{equation*}
        \begin{aligned}
            R_N^{(0)}/2 \leq &\frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
            +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
            +& \frac{{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),
        \end{aligned}
    \end{equation*}
    where $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$ and
    \begin{gather*}
        {\sigma_G^{(q)}}^2=\frac{\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}\\
        +\alpha_B\sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]
        +\frac{\sigma^2}{B}.
    \end{gather*}

\label{R_2 bound multi}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{(1+\tilde{\epsilon})\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then
\begin{equation*}
    \begin{aligned}
        R_N^{(0)}/2\leq & \frac{2(1+\tilde{\epsilon})\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
        +&\frac{{\sigma_M^{(q)}}^2}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),
    \end{aligned}
\end{equation*}
where $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$ and
\begin{gather*}
    \tilde{\epsilon}=8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+4\epsilon_p+4\epsilon_a(1+\epsilon_p),\\
    {\sigma_M^{(q)}}^2=\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right).
\end{gather*}

By Lemma \ref{Refine excess risk decomposition}, (\ref{eq: b1}), (\ref{eq: b2}), (\ref{eq: c1}) and Lemma \ref{R_2 bound}, we have
\begin{equation*}
    \begin{aligned}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]\leq 2\mathrm{VarErr}+2\mathrm{BiasErr}+\mathrm{ApproxErr},
    \end{aligned}
\end{equation*}
where
\begin{gather*}
    \mathrm{VarErr}=\frac{2\alpha_B\left(\frac{\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)+{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),\\
    \mathrm{BiasErr}=\frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
    \mathrm{ApproxErr}=\left\|\mathbf{w}^*\right\|_{\mathbf{D}_2^{\mathbf{H}}}^2
    +\frac{1}{2}\|\mathbf{w}^*\|_{\mathbf{D}_1^{\mathbf{H}}}^2,
\end{gather*}
with $\mathbf{D}=\mathbf{H}^{(q)}-\mathbf{H}$, $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$,  and
\begin{gather*}
    \mathbf{D}_2^{\mathbf{H}}=\mathbf{H}(\mathbf{H}^{(q)})^{-1}\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\mathbf{D}(\mathbf{H}^{(q)})^{-1}\mathbf{H},\ \mathbf{D}_1^{\mathbf{H}}=\mathbf{D}(\mathbf{H}^{(q)})^{-1}\mathbf{H}(\mathbf{H}^{(q)})^{-1}\mathbf{D},\\
    {\sigma_G^{(q)}}^2=\frac{\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}\\
    +\alpha_B\sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]
    +\frac{\sigma^2}{B}.
\end{gather*}
Let the initialization $\mathbf{w}_0=0$ completes the proof.

\label{Theorem 1, proof}
Under Assumption \ref{ass1}, \ref{ass: addd quantized}, \ref{ass2} and \ref{ass3}, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, and the stepsize satisfies $\gamma < \frac{1}{ \alpha_B (1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}(\mathbf{H})}$, then the excess risk can be upper bounded as follows.
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{1+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{VarErr}\lesssim\left(\frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\sum_{i>k^*}\lambda_i^2\right) \frac{\frac{(1+\epsilon_o)\sigma^2}{B}+\alpha_B \sigma_M^2}{1-\gamma\alpha_B(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}\left(\mathbf{H}\right)},
    \end{aligned}
\end{equation*}
with 
\begin{equation*}
    \sigma_M^2=[\epsilon_o+(1+\epsilon_o)(\epsilon_p+\epsilon_a(1+\epsilon_p))]\left\|\mathbf{w}^*\right\|_\mathbf{H}^2
+(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right).
\end{equation*}

By Lemma \ref{Refine excess risk decomposition}, Lemma \ref{lem: b1}, (\ref{eq: c1}) and Lemma \ref{R_2 bound multi}, we have
\begin{equation*}
    \begin{aligned}
        \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]\leq 2\mathrm{VarErr}+2\mathrm{BiasErr}+\mathrm{ApproxErr},
    \end{aligned}
\end{equation*}
where
\begin{gather*}
    \mathrm{VarErr}=\frac{{\sigma_M^{(q)}}^2+2(1+\tilde{\epsilon})\alpha_B\left(\frac{\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{1-(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),\\
    \mathrm{BiasErr}=\frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
    \mathrm{ApproxErr}=\frac{\epsilon_d^2}{2(1+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\epsilon_d}{(1+\epsilon_d)^2}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2\lesssim \frac{\epsilon_d}{1+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,
\end{gather*}
with $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$ and
\begin{gather*}
        \tilde{\epsilon}=8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+4\epsilon_p+4\epsilon_a(1+\epsilon_p)\lesssim \epsilon_o+(1+\epsilon_o)(\epsilon_p+\epsilon_a(1+\epsilon_p)),\\
        {\sigma_M^{(q)}}^2=\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+2\epsilon_p \right)\\
        \lesssim \frac{(1+\epsilon_o)\sigma^2}{B} + {\|\mathbf{w}^*\|_\mathbf{H}^2}\alpha_B\left(\epsilon_o+(1+\epsilon_o)(\epsilon_p+\epsilon_a(1+\epsilon_p)) \right).
\end{gather*}
Let initialization $\mathbf{w}_0=0$. Regarding $\mathrm{VarErr}$, noticing that
$1+\tilde{\epsilon}\lesssim (1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)]$,
we have
\begin{equation*}
    \begin{aligned}
        &{\sigma_M^{(q)}}^2+2(1+\tilde{\epsilon})\alpha_B\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)\\
        \lesssim&\frac{(1+\epsilon_o)\sigma^2}{B}+\alpha_B\left\|\mathbf{w}^*\right\|_\mathbf{H}^2\left(\epsilon_o+(1+\epsilon_o)(\epsilon_p+\epsilon_a(1+\epsilon_p)) \right)\\
        +&\alpha_B(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right).
    \end{aligned}
\end{equation*}
Then the proof is completed by $\mathrm{tr}(\mathbf{H}^{(q)})=(1+\epsilon_d)\mathrm{tr}(\mathbf{H})$ and $\lambda_i^{(q)}=(1+\epsilon_d)\lambda_i$.

\label{theorem new 2.5, proof}
Under Assumption \ref{ass1}, \ref{ass: addd quantized}, \ref{ass2} and \ref{ass3}, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-additive, and the stepsize satisfies $\gamma < \frac{1}{\alpha_B [\mathrm{tr}(\mathbf{H})+d\epsilon_d]}$, then
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{ VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{align*}
        &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{\lambda_d+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{VarErr}\lesssim \frac{\alpha_B\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)+\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+\alpha_B \epsilon_p[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}{1-\gamma\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right).
\end{align*}

By Theorem \ref{Theorem 4},
\begin{equation*}
    \mathbb{E}[\mathcal E(\overline{\mathbf{w}}_N)]\leq 2\mathrm{VarErr}+2\mathrm{BiasErr}+\mathrm{ApproxErr},
\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        &\mathrm{VarErr}\leq\frac{2\alpha_B\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)+{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right),\\
        &\mathrm{BiasErr}\leq\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{ApproxErr}\leq\left\|\mathbf{w}^*\right\|_{\mathbf{D}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{H}(\mathbf{H}+\mathbf{D})^{-1}\mathbf{D}}^2+\|\mathbf{w}^*\|_{\mathbf{D}_\mathbf{H}}^2,
    \end{aligned}
\end{equation*}
with ${\sigma_G^{(q)}}^2=\frac{\sigma^2+\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}+\alpha_B\sup_t\mathbb{E}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right)\right]$ and $\mathbf{D}_{\mathbf{H}}=\mathbf{H}(\mathbf{H}^{(q)})^{-1}\frac{1}{N\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^N\right)(\mathbf{H}^{(q)})^{-1}\mathbf{D}(\mathbf{H}^{(q)})^{-1}\mathbf{H}$.

Under additive quantization, it holds
\begin{equation*}
    \mathrm{tr}(\mathbf{H}^{(q)}) = \mathrm{tr}(\mathbf{H})+d\epsilon_d,\quad \sum_{i>k^*}(\lambda_i^{(q)})^2=\sum_{i>k^*}(\lambda_i+\epsilon_d)^2,
\end{equation*}
and
\begin{equation*}
    {\sigma_G^{(q)}}^2=\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+\alpha_B \epsilon_p[\mathrm{tr}(\mathbf{H})+d\epsilon_d].
\end{equation*}
Then we have
\begin{equation*}
    \mathrm{VarErr}\lesssim \frac{\alpha_B\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)+\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+\alpha_B \epsilon_p[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}{1-\gamma\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right).
\end{equation*}
The proof is completed by Lemma \ref{lem: b2}:
\begin{equation*}
    \mathrm{ApproxErr}\leq \frac{\epsilon_d^2}{2(\lambda_d+\epsilon_d)^2}\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\lambda_1\epsilon_d}{(\lambda_d+\epsilon_d)(\lambda_1+\epsilon_d)}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2\lesssim \frac{\epsilon_d}{\lambda_d+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2.
\end{equation*}

Recall that $k_0^*=\max\{k: \lambda_k \geq \frac{1}{N\gamma}\}$,
\begin{equation*}
    \begin{aligned}
        R_0=&\underbrace{\left(\frac{k_0^*}{N}+N\gamma^2\cdot\sum_{i>k_0^*}\lambda_i^2\right)\frac{\alpha_B\left(\frac{1}{N\gamma}\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right)
        +\frac{\sigma^2}{B}}{1-\gamma\alpha_B\mathrm{tr}\left(\mathbf{H}\right)}}_{\rm EffectiveVar}\\
        +&\underbrace{\frac{1}{\gamma^2N^2}\cdot\|      {\mathbf{w}}^*\|_{(\mathbf{H}_{0:k_0^*})^{-1}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}_{\rm EffectiveBias},
    \end{aligned}
\end{equation*}
and by Theorem \ref{Theorem 1, proof},
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{1+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\leq\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{VarErr}\lesssim\left(\frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\sum_{i>k^*}\lambda_i^2\right) \frac{\frac{(1+\epsilon_o)\sigma^2}{B}+\alpha_B\sigma_M^2}{1-\gamma\alpha_B(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}\left(\mathbf{H}\right)},
    \end{aligned}
\end{equation*}
with 
\begin{equation*}
    \sigma_M^2=[\epsilon_o+(1+\epsilon_o)(\epsilon_p+\epsilon_a(1+\epsilon_p))]\left\|\mathbf{w}^*\right\|_\mathbf{H}^2
    +(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right).
\end{equation*}

We then compare the upper bound of $\mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]$ with $R_0$. Regarding $\mathrm{VarErr}$, we first analyze $\frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\sum_{i>k^*}\lambda_i^2$. Note that for $k_0^*< i \leq k^*$, $\frac{1}{N\gamma(1+\epsilon_d)}\leq\lambda_i<\frac{1}{N\gamma}$, we have
\begin{equation*}
    \begin{aligned}
        &\frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\cdot\sum_{i>k^*}\lambda_i^2\\
        =&\frac{k_0^*}{N}+\frac{k^*-k_0^*}{N}-N\gamma^2(1+\epsilon_d)^2\cdot\sum_{k_0^*<i\leq k^*}\lambda_i^2+N\gamma^2(1+\epsilon_d)^2\cdot\sum_{i>k_0^*}\lambda_i^2\\
        \leq &\frac{k_0^*}{N}+\frac{k^*-k_0^*}{N}-N\gamma^2(1+\epsilon_d)^2(k^*-k_0^*)\frac{1}{N^2\gamma^2(1+\epsilon_d)^2}+N\gamma^2(1+\epsilon_d)^2\cdot\sum_{i>k_0^*}\lambda_i^2\\
        =&\frac{k_0^*}{N}+N\gamma^2(1+\epsilon_d)^2\cdot\sum_{i>k_0^*}\lambda_i^2.
    \end{aligned}
\end{equation*}
We then analyze $\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2$. Similarly,
\begin{equation*}
    \begin{aligned}
        &\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
        =&\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k_0^*}^{(q)}}^2}{N\gamma}+\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{k_0^*:k^*}^{(q)}}^2}{N\gamma}-\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:k^*}^{(q)}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:\infty}^{(q)}}^2\\
        \leq &\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k_0^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:\infty}^{(q)}}^2\\
        \leq &\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2.
    \end{aligned}
\end{equation*}
Therefore, the sufficient conditions for $\mathrm{VarErr}\lesssim \mathrm{EffectiveVar}$ are
\begin{equation*}
    \epsilon_d\lesssim 1,\quad  \epsilon_o,\epsilon_a,\epsilon_p \lesssim  \left(\frac{\sigma^2}{B\alpha_B\|\mathbf{w}^*\|_\mathbf{H}^2}+\frac{\frac{1}{N\gamma}\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\|\mathbf{w}^*\|_\mathbf{H}^2}\right)\wedge 1,
\end{equation*}

Secondly, we analyze $\mathrm{BiasErr}$. Similarly,
\begin{equation}
    \label{eq: d1}
    \begin{aligned}
        & \frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
        =&\frac{1}{\gamma^2N^2}\cdot\left(\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k_0^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{k_0^*:k^*}^{(q)})^{-1}}^2\right)-\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:k^*}^{(q)}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:\infty}^{(q)}}^2\\
        \leq &\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k_0^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:\infty}^{(q)}}^2\\
        \leq&\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}}^*\|_{(\mathbf{H}_{0:k_0^*})^{-1}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2=\mathrm{EffectiveBias}.
    \end{aligned}
\end{equation}
Thirdly, the sufficient condition for $\mathrm{ApproxErr}\lesssim R_0$ is $\epsilon_d\lesssim \frac{R_0}{\|\mathbf{w}^*\|_{\mathbf{H}}^2}.$ Overall, we require
\begin{equation*}
    \epsilon_d\lesssim 1\wedge \frac{R_0}{\|\mathbf{w}^*\|_{\mathbf{H}}^2},\quad\epsilon_o,\epsilon_a,\epsilon_p \lesssim  \left(\frac{\sigma^2}{B\alpha_B\|\mathbf{w}^*\|_\mathbf{H}^2}+\frac{\frac{1}{N\gamma}\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\|\mathbf{w}^*\|_\mathbf{H}^2}\right)\wedge 1.
\end{equation*}

Recall that $k_0^*=\max\{k: \lambda_k \geq \frac{1}{N\gamma}\}$,
\begin{equation*}
    \begin{aligned}
        R_0=&\underbrace{\left(\frac{k_0^*}{N}+N\gamma^2\cdot\sum_{i>k_0^*}\lambda_i^2\right)\frac{\alpha_B\left(\frac{1}{N\gamma}\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right)
        +\frac{\sigma^2}{B}}{1-\gamma\alpha_B\mathrm{tr}\left(\mathbf{H}\right)}}_{\rm EffectiveVar}\\
        +&\underbrace{\frac{1}{\gamma^2N^2}\cdot\|      {\mathbf{w}}^*\|_{(\mathbf{H}_{0:k_0^*})^{-1}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}_{\rm EffectiveBias},
    \end{aligned}
\end{equation*}
and by Corollary \ref{theorem new 2.5, proof},
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{ VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{align*}
    &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{\lambda_d+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
    &\mathrm{VarErr}\lesssim \frac{\alpha_B\left(\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)+\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+\alpha_B \epsilon_p[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}{1-\gamma\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right).
\end{align*}
We then compare the upper bound of $\mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]$ with $R_0$. Regarding $\mathrm{VarErr}$, we first analyze $\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2$. Recall that for $k_0^*< i \leq k^*$, $\frac{1}{N\gamma}-\epsilon_d\leq\lambda_i<\frac{1}{N\gamma}$,
\begin{equation*}
    \begin{aligned}
        \frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i+\epsilon_d)^2
        =&\frac{k_0^*}{N}+\frac{k^*-k_0^*}{N}-N\gamma^2\sum_{k_0^*<i\leq k^*}(\lambda_i+\epsilon_d)^2+N\gamma^2\sum_{i>k_0^*}(\lambda_i+\epsilon_d)^2\\
        \leq&\frac{k_0^*}{N}+N\gamma^2\sum_{i>k_0^*}(\lambda_i+\epsilon_d)^2.
    \end{aligned}
\end{equation*}
We then analyze $\frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2$. Similarly,
\begin{equation}
    \label{eq: d1'}
    \begin{aligned}
        \frac{\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2}{N\gamma}+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\leq \frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2.
    \end{aligned}
\end{equation}
Therefore, the sufficient conditions for $\mathrm{VarErr}\lesssim \mathrm{EffectiveVar}$ are
\begin{gather*}
    \epsilon_d\lesssim \sqrt{\frac{\frac{k_0^*}{N}+N\gamma^2\cdot\sum_{i>k_0^*}\lambda_i^2}{N\gamma^2(d-k_0^*)}},\quad \epsilon_p\lesssim \frac{\sigma^2}{B\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}+\frac{\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\mathrm{tr}(\mathbf{H})+d\epsilon_d}, \\ \epsilon_a,\epsilon_o\lesssim \sigma^2+B\alpha_B\left(\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right).
\end{gather*}

Secondly, we analyze $\mathrm{BiasErr}$. Similarly,
\begin{equation*}
    \begin{aligned}
        & \frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
        =&\frac{1}{\gamma^2N^2}\cdot\left(\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k_0^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{k_0^*:k^*}^{(q)})^{-1}}^2\right)-\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:k^*}^{(q)}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:\infty}^{(q)}}^2\\
        \leq &\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k_0^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k_0^*:\infty}^{(q)}}^2\\
        \leq&\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}}^*\|_{(\mathbf{H}_{0:k_0^*})^{-1}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2=\mathrm{EffectiveBias}.
    \end{aligned}
\end{equation*}
Thirdly, the sufficient condition for $\mathrm{ApproxErr}\lesssim R_0$ is $\epsilon_d\lesssim \frac{R_0}{\|\mathbf{w}^*\|_{\mathbf{H}}^2}\lambda_d.$ Overall, we require
\begin{gather*}
    \epsilon_d\lesssim \sqrt{\frac{\frac{k_0^*}{N}+N\gamma^2\cdot\sum_{i>k_0^*}\lambda_i^2}{N\gamma^2(d-k_0^*)}}\wedge \frac{R_0\lambda_d}{\|\mathbf{w}^*\|_{\mathbf{H}}^2},\quad \epsilon_a,\epsilon_o\lesssim \sigma^2+B\alpha_B\left(\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right), \\ 
    \epsilon_p\lesssim \frac{\sigma^2}{B\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}+\frac{\frac{\|{\mathbf{w}}^*\|_{\mathbf{I}_{0:k_0^*}}^2}{N\gamma}+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2}{\mathrm{tr}(\mathbf{H})+d\epsilon_d}.
\end{gather*}

We prove by applying Theorem \ref{Theorem 1}:
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{1+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{VarErr}\lesssim\left(\frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\sum_{i>k^*}\lambda_i^2\right) \frac{\frac{(1+\epsilon_o)\sigma^2}{B}+\alpha_B(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\left\|\mathbf{w}^*\right\|_\mathbf{H}^2}{1-\gamma\alpha_B(1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}\left(\mathbf{H}\right)}.
    \end{aligned}
\end{equation*}

We first deal with $\mathrm{VarErr}$ under power-law spectrum Assumption \ref{assumption 1}. Under multiplicative quantization, we can estimate $k^*$ by 
\begin{equation*}
    (1+\epsilon_d){k^*}^{-a}\approx \frac{1}{N\gamma},
\end{equation*}
that is
\begin{equation}
\label{estimate k*}
    k^*\approx \left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}.
\end{equation}
Further, the power-law Assumption \ref{assumption 1} also implies that for any positive $k$,
\begin{equation}
\label{estimate tail}
    \sum_{i>k} i^{-a}\approx k^{1-a}.
\end{equation}
By (\ref{estimate k*}) and (\ref{estimate tail}),
\begin{equation*}
    \begin{aligned}
        \frac{k^*}{N}+N\gamma^2(1+\epsilon_d)^2\sum_{i>k^*}\lambda_i^2\lesssim &\frac{\min\left\{d,\left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}+N\gamma^2(1+\epsilon_d)^2\left[N\gamma (1+\epsilon_d)\right]^{\frac{1-2a}{a}}\right\}}{N}\\
        \lesssim&\frac{\min \left\{d,\left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}\right\}}{N}.
    \end{aligned}
\end{equation*}
Moreover, under polynomial spectrum Assumption \ref{assumption 1}, 
\begin{equation*}
    \mathrm{tr}(\mathbf{H})\eqsim 1,\quad \mathbb{E}\|\mathbf{w}^*\|_\mathbf{H}^2 \eqsim 1.
\end{equation*}
Therefore, under Assumption \ref{assumption 1}, by applying stepsize $\gamma < \frac{1}{2\alpha_B (1+\epsilon_o)[1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)\mathrm{tr}(\mathbf{H})}$ and taking expectation on $\mathbf{w}^*$, it holds that
\begin{equation}
    \label{eq: d4}
    \mathbb{E}_{\mathbf{w}^*}\mathrm{VarErr}\lesssim \frac{\min \left\{d,\left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}\right\}}{N}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)],
\end{equation}
where we use $\sigma^2\lesssim 1$.

We secondly deal with $\mathrm{BiasErr}$. Under Assumption \ref{assumption 1}, using (\ref{eq: d1}),
\begin{equation}
    \label{eq: d5}
    \begin{aligned}
        \mathbb{E}_{\mathbf{w}^*}\mathrm{BiasErr}\leq&
        \mathbb{E}_{\mathbf{w}^*}\left[\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}}^*\|_{(\mathbf{H}_{0:k_0^*})^{-1}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right]\\
        =&\frac{1}{N^2\gamma^2}\sum_{i=1}^{k_0^*}\lambda_i^{-1}+\sum_{i>k_0^*}^{d}\lambda_i\\
        \leq& \frac{k_0^*}{N\gamma}+\sum_{i>k_0^*}^{d}\lambda_i\\
        \eqsim&\frac{k_0^*}{N\gamma}+(k_0^*)^{1-a}\\
        \lesssim&\max\left\{d^{1-a},(N\gamma)^{1/a-1}\right\}.
    \end{aligned}
\end{equation}

Therefore, together with (\ref{eq: d4}) and (\ref{eq: d5}), and taking expectation on $\mathbf{w}^*$, we have
\begin{equation*}
    \begin{aligned}
        &\mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]\lesssim  \frac{\epsilon_d}{1+\epsilon_d}+\max\left\{d^{1-a},(N\gamma)^{1/a-1}\right\}+\frac{\min \left\{d,\left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}\right\}}{N}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)].
    \end{aligned}
\end{equation*}
Denote $R=\mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]-\frac{\epsilon_d}{1+\epsilon_d}$.
\begin{itemize}[leftmargin=*,nosep]
    \item $d>\left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}$

    In this case,
    \begin{equation*}
        \begin{aligned}
            R\lesssim& (N\gamma)^{1/a-1}+\frac{\left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}}{N}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\\
            \lesssim& N^{1/a-1}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)^{1/a}.
        \end{aligned}
    \end{equation*}
    \item $(N\gamma)^{1/a}<d\leq \left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}$

    In this case,
    \begin{equation*}
        \begin{aligned}
            R\lesssim& (N\gamma)^{1/a-1}+(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\frac{d}{N}\\
            \lesssim& (N\gamma)^{1/a-1}+(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\frac{\left[N\gamma (1+\epsilon_d)\right]^{\frac{1}{a}}}{N}\\
            \lesssim&N^{1/a-1}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)^{1/a}.
        \end{aligned}
    \end{equation*}
    \item $d\leq (N\gamma)^{1/a}$

    In this case,
    \begin{equation*}
        \begin{aligned}
            R\lesssim& d^{1-a}+(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]\frac{d}{N}\\
            \lesssim&d^{1-a}+(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)]N^{1/a-1}.
        \end{aligned}
    \end{equation*}
\end{itemize}
Overall,
\begin{equation*}
    \mathbb{E}\left[\mathcal{E}(\overline{\mathbf{w}}_N)\right]\lesssim\frac{\epsilon_d}{1+\epsilon_d}+d^{1-a}+N^{1/a-1}(1+\epsilon_o) [1+\epsilon_p+\epsilon_a(1+\epsilon_p)](1+\epsilon_d)^{1/a}.
\end{equation*}

We prove by applying Corollary \ref{theorem new 2.5}:
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)] \lesssim \mathrm{ApproxErr}+\mathrm{ VarErr}+\mathrm{BiasErr},
\end{equation*}
where
\begin{align*}
        &\mathrm{ApproxErr}\lesssim \frac{\epsilon_d}{\lambda_d+\epsilon_d}\left\|\mathbf{w}^*\right\|_\mathbf{H}^2,\quad \mathrm{BiasErr}\lesssim\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2,\\
        &\mathrm{VarErr}\lesssim \frac{\alpha_B\|\mathbf{w}^*\|_\mathbf{H}^2+\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+\alpha_B \epsilon_p[\mathrm{tr}(\mathbf{H})+p\epsilon_d]}{1-\gamma\alpha_B[\mathrm{tr}(\mathbf{H})+p\epsilon_d]}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right).
\end{align*}
We first deal with $\mathrm{BiasErr}$.
Under Assumption \ref{assumption 1}, using (\ref{eq: d1'}),
\begin{equation}
    \label{eq: d6}
    \begin{aligned}
        \mathbb{E}_{\mathbf{w}^*}\mathrm{BiasErr}\leq&
        \mathbb{E}_{\mathbf{w}^*}\left[\frac{1}{\gamma^2N^2}\cdot\|{\mathbf{w}}^*\|_{(\mathbf{H}_{0:k_0^*})^{-1}}^2+\|{\mathbf{w}}^*\|_{\mathbf{H}_{k_0^*:\infty}}^2\right]\\
        =&\frac{1}{N^2\gamma^2}\sum_{i=1}^{k_0^*}\lambda_i^{-1}+\sum_{i>k_0^*}^{d}\lambda_i\\
        \leq& \frac{k_0^*}{N\gamma}+\sum_{i>k_0^*}^{d}\lambda_i\\
        =&\frac{k_0^*}{N\gamma}+(k_0^*)^{1-a}\\
        \lesssim&\max\left\{d^{1-a},(N\gamma)^{1/a-1}\right\}.
    \end{aligned}
\end{equation}
We then analyze $\mathrm{VarErr}$. If $\epsilon_d+d^{-a}\geq \frac{1}{N\gamma}$, then
\begin{equation*}
    \begin{aligned}
        \frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2=\frac{d}{N}.
    \end{aligned}
\end{equation*}
Otherwise,
\begin{equation*}
    \begin{aligned}
        &\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\\
        \lesssim&\frac{\left(\frac{1}{N\gamma}-\epsilon_d\right)^{-1/a}+N^2\gamma^2\left(\frac{1}{N\gamma}-\epsilon_d\right)^{-(1-2a)/a}+\epsilon_d^2N^2\gamma^2\left[d-\left(\frac{1}{N\gamma}-\epsilon_d\right)^{-1/a}\right]}{N}\\
        \lesssim&\frac{\left(\frac{1}{N\gamma}-\epsilon_d\right)^{-1/a}+\epsilon_d^2N^2\gamma^2\left[d-\left(\frac{1}{N\gamma}-\epsilon_d\right)^{-1/a}\right]}{N}.
    \end{aligned}
\end{equation*}
Denote $k_{\rm eff}=\left[d^{-a}\vee \left(\frac{1}{N\gamma}-\epsilon_d\right)\right]^{-1/a}$, it follows that
\begin{equation*}
    \frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\lesssim\frac{k_{\rm eff}+\epsilon_d^2N^2\gamma^2(d-k_{\rm eff})}{N}.
\end{equation*}
Hence, under Assumption \ref{assumption 1}, taking expectation on $\mathbf{w}^*$ and applying stepsize $\gamma < \frac{1}{2 \alpha_B [\mathrm{tr}(\mathbf{H})+p\epsilon_d]}$,
\begin{equation}
    \label{eq: d8}\mathbb{E}_{\mathbf{w}^*}\mathrm{VarErr}\lesssim \left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{k_{\rm eff}+\epsilon_d^2N^2\gamma^2(d-k_{\rm eff})}{N}.
\end{equation}

Therefore, together with (\ref{eq: d6}) and (\ref{eq: d8}), and taking expectation on $\mathbf{w}^*$, we have
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]\lesssim  \frac{\epsilon_d}{d^{-a}+\epsilon_d}+\max\left\{d^{1-a},(N\gamma)^{1/a-1}\right\}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{k_{\rm eff}+\epsilon_d^2N^2\gamma^2(d-k_{\rm eff})}{N}.
\end{equation*}
Denote $R=\mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]-  \frac{\epsilon_d}{d^{-a}+\epsilon_d}$.
\begin{itemize}[leftmargin=*,nosep]
    \item $d^{-a}\leq {1}/{(N\gamma)}-\epsilon_d$

    In this case, let $\epsilon_d'=d^a\epsilon_d$. Then $d^{-a}\leq {1}/{(N\gamma)}-d^{-a}\epsilon_d'$. That is, $d^{-a}\leq \frac{1}{N\gamma(1+\epsilon_d')}$.
    \begin{equation*}
        \begin{aligned}
            R\lesssim& (N\gamma)^{1/a-1}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{\left(\frac{1}{N\gamma}-\epsilon_d\right)^{-1/a}+\epsilon_d^2N^2\gamma^2\left(d-\left(\frac{1}{N\gamma}-\epsilon_d\right)^{-1/a}\right)}{N}\\
            =& (N\gamma)^{1/a-1}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{\left(\frac{1}{N\gamma}-d^{-a}\epsilon_d'\right)^{-1/a}(1-\epsilon_d^2N^2\gamma^2)+\epsilon_d^2N^2\gamma^2d}{N}\\
            \leq& (N\gamma)^{1/a-1}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{(1+\epsilon_d')^{1/a}(N\gamma)^{1/a}(1-\epsilon_d^2N^2\gamma^2)+\epsilon_d^2N^2\gamma^2d}{N}\\
            \leq& (N\gamma)^{1/a-1}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\left[\frac{(1+\epsilon_d')^{1/a}(N\gamma)^{1/a}}{N}+\epsilon_d^2N\gamma^2d\right].
        \end{aligned}
    \end{equation*}
    We then focus on $\epsilon_d^2N\gamma^2d$. By $N\gamma \leq \frac{d^{a}}{1+\epsilon_d'}$, we have
    \begin{equation*}
        \epsilon_d^2N\gamma^2d \lesssim \frac{\epsilon_d^2}{1+\epsilon_d'}d^{1+a}=\frac{(\epsilon_d')^2}{1+\epsilon_d'}d^{1-a}.
    \end{equation*}
    Therefore,
    \begin{equation*}
        \begin{aligned}
            R\lesssim N^{1/a-1}(1+d^a\epsilon_d)^{1/a}\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{(d^a\epsilon_d)^2}{1+d^a\epsilon_d}d^{1-a}.
        \end{aligned}
    \end{equation*}
    \item $\frac{1}{N\gamma}-\epsilon_d<d^{-a}\leq \frac{1}{N\gamma}$

    In this case, $\frac{1}{N\gamma}-d^{-a}\epsilon_d'<d^{-a}$, that is, $d^{a}<N\gamma(1+\epsilon_d')$. Consequently,
    \begin{equation*}
        \begin{aligned}
            R\lesssim&(N\gamma)^{1/a-1}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{d}{N}\\
            \lesssim&(N\gamma)^{1/a-1}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)(1+\epsilon_d')^{1/a}N^{1/a-1}\\
            \lesssim&\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)(1+d^a\epsilon_d)^{1/a}N^{1/a-1}.
        \end{aligned}
    \end{equation*}
    \item $d^{-a}>\frac{1}{N\gamma}$

    In this case,
    \begin{equation*}
        \begin{aligned}
            R\lesssim&d^{1-a}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\frac{d}{N}\\
            \lesssim&d^{1-a}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)N^{1/a-1}.
        \end{aligned}
    \end{equation*}
\end{itemize}
Overall,
\begin{equation*}
    \mathbb{E}[\mathcal{E}(\overline{\mathbf{w}}_N)]\lesssim \frac{d^a\epsilon_d}{1+d^a\epsilon_d}+\left(1+\frac{\epsilon_o+\epsilon_a}{B}+\epsilon_p(1+d\epsilon_d)\right)\left[N^{\frac{1}{a}-1}(1+d^a\epsilon_d)^{\frac{1}{a}}+d^{1-a}\left(1+\frac{(d^a\epsilon_d)^2}{1+d^a\epsilon_d}\right)\right].
\end{equation*}

\label{ass2 raw data}
    Assume there exists a positive constant $\alpha_0>0$, such that for any PSD matrix $\mathbf{A}$, it holds that
    \begin{equation*}
        \mathbb{E}\left[{\mathbf{x}}{\mathbf{x}}^\top\mathbf{A}{\mathbf{x}}{\mathbf{x}}^\top\right]\preceq\alpha_0\operatorname{tr}(\mathbf{H}\mathbf{A})\mathbf{H}.
    \end{equation*}

\label{assumption noise raw}
    Assume there exists a constant $\sigma_0^2$ such that
    \begin{equation*}
        \mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2\mathbf{x}\mathbf{x}^\top\right]\preceq\sigma_0^{2}\mathbf{H}.
    \end{equation*}

\label{example G1}
    We consider a strong multiplicative quantization. In this case, there exist constants $\epsilon_d,\epsilon_d'$ such that
    \begin{equation*}
          \mathbb{E}\left[\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\big| \mathbf{x}\right]=\epsilon_d\mathbf{x}\mathbf{x}^\top,\quad\mathbb{E}\left[\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\mathbf{A}\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\Big| \mathbf{x}\right]\preceq \epsilon_d' \mathbf{x}\mathbf{x}^\top \mathbf{A}\mathbf{x}\mathbf{x}^\top.
    \end{equation*}

\label{exampleG2}
    We consider a strong additive quantization. In this case, there exist constants $\epsilon_d, \epsilon_d'$ such that
    \begin{equation}                    
        \mathbb{E}\left[\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\big| \mathbf{x}\right]=\epsilon_d\mathbf{I},\quad\mathbb{E}\left[\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\mathbf{A}\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\Big| \mathbf{x}\right]\preceq \epsilon_d' \mathrm{tr}(\mathbf{A})\mathbf{I}.
    \end{equation}

Under strong multiplicative quantization \ref{example G1} and Assumption \ref{ass2 raw data}, 
\begin{equation*}
    \begin{aligned}
        \mathbb{E}\left[{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\mathbf{A}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\lesssim\alpha_0{(1+\epsilon_d+\epsilon_d')}\mathrm{tr}(\mathbf{H}^{(q)}\mathbf{A})\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

We proof by (\ref{G0}).
From Assumption \ref{ass2 raw data},
\begin{equation}
    \label{G1}
    \mathbb{E}\left[{\mathbf{x}}{\mathbf{x}}^\top\mathbf{A}{\mathbf{x}}{\mathbf{x}}^\top\right]\preceq\alpha_0\operatorname{tr}(\mathbf{H}\mathbf{A})\mathbf{H}.
\end{equation}
Under strong multiplicative quantization \ref{example G1}, we have
\begin{equation}
    \label{G2}
    \mathbb{E}\left[\left({\boldsymbol{\epsilon}^{(d)}}^\top\mathbf{A}{\boldsymbol{\epsilon}^{(d)}}\right){\mathbf{x}}{\mathbf{x}}^\top\right]=\epsilon_d\mathbb{E}\left[{\mathbf{x}}{\mathbf{x}}^\top\mathbf{A}{\mathbf{x}}{\mathbf{x}}^\top\right]\preceq\epsilon_d\alpha_0\operatorname{tr}(\mathbf{H}\mathbf{A})\mathbf{H},
\end{equation}
\begin{equation}
    \label{G3}
    \mathbb{E}\left[\left({\mathbf{x}}^\top\mathbf{A}{\mathbf{x}}\right)\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\right]=\epsilon_d\mathbb{E}\left[{\mathbf{x}}{\mathbf{x}}^\top\mathbf{A}{\mathbf{x}}{\mathbf{x}}^\top\right]\preceq\epsilon_d\alpha_0\operatorname{tr}(\mathbf{H}\mathbf{A})\mathbf{H},
\end{equation}
and
\begin{equation}
    \label{G4}
    \mathbb{E}\left[\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\mathbf{A}\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\preceq\epsilon_d'\mathbb{E}\left[{\mathbf{x}}{\mathbf{x}}^\top\mathbf{A}{\mathbf{x}}{\mathbf{x}}^\top\right]\preceq\epsilon_d'\alpha_0\operatorname{tr}(\mathbf{H}\mathbf{A})\mathbf{H}.
\end{equation}
Therefore, together with (\ref{G0}), (\ref{G1}), (\ref{G2}), (\ref{G3}) and (\ref{G4}), we have
\begin{equation*}
    \begin{aligned}
        \mathbb{E}\left[{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\mathbf{A}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\lesssim\alpha_0(1+\epsilon_d+\epsilon_d')\mathrm{tr}(\mathbf{H}\mathbf{A})\mathbf{H}\leq\alpha_0{(1+\epsilon_d+\epsilon_d')}\mathrm{tr}(\mathbf{H}^{(q)}\mathbf{A})\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}
That is, under strong multiplicative quantization Example \ref{example G1} and fourth moment Assumption \ref{ass2 raw data} on full-precision data, Assumption \ref{ass2} is verified.

Under strong additive quantization \ref{exampleG2} and Assumption \ref{ass2 raw data},
\begin{equation*}
    \begin{aligned}
        \mathbb{E}\left[{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\mathbf{A}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\lesssim(1+\alpha_0)\left(1+\frac{\epsilon_d'}{\epsilon_d^2}\right)\mathrm{tr}(\mathbf{H}^{(q)}\mathbf{A})\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

We proof by (\ref{G0}). Under strong additive quantization \ref{exampleG2},
\begin{equation}
    \label{G5}
    \mathbb{E}\left[\left({\boldsymbol{\epsilon}^{(d)}}^\top\mathbf{A}{\boldsymbol{\epsilon}^{(d)}}\right){\mathbf{x}}{\mathbf{x}}^\top\right]\preceq \epsilon_d\operatorname{tr}(\mathbf{A})\mathbf{H},
\end{equation}
\begin{equation}
    \label{G6}
    \mathbb{E}\left[\left({\mathbf{x}}^\top\mathbf{A}{\mathbf{x}}\right)\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\preceq \epsilon_d\operatorname{tr}(\mathbf{H}\mathbf{A})\mathbf{I},
\end{equation}
and
\begin{equation}
    \label{G7}
    \mathbb{E}\left[\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\mathbf{A}\boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\preceq\epsilon_d'\operatorname{tr}(\mathbf{A})\mathbf{I}.
\end{equation}

Therefore, together with (\ref{G0}), (\ref{G5}), (\ref{G6}) and (\ref{G7}), we have
\begin{equation*}
    \begin{aligned}
        \mathbb{E}\left[{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\mathbf{A}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\lesssim(1+\alpha_0)\left(1+\frac{\epsilon_d'}{\epsilon_d^2}\right)\mathrm{tr}(\mathbf{H}^{(q)}\mathbf{A})\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}
That is, under strong additive quantization Example \ref{exampleG2} and fourth moment Assumption \ref{ass2 raw data} on full-precision data, Assumption \ref{ass2} is verified.

Under strong multiplicative quantization \ref{example G1}, Assumption \ref{ass2 raw data}, and Assumption \ref{assumption noise raw},
\begin{equation*}
    \begin{aligned}
        \mathbb{E}\left[(y^{(q)}-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x}^{(q)}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]
        \precsim \left(\sigma_0^2+\epsilon_l+\frac{1+\epsilon_d+\epsilon_d'}{1+\epsilon_d}\alpha_0\|\mathbf{w}^*\|_\mathbf{H}^2\right)\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

Regarding $\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]$,
\begin{equation}
\label{G9}
    \begin{aligned}
        \mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right] \preceq& 2\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\mathbf{x}}{\mathbf{x}}^\top\right]+2\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\boldsymbol{\epsilon}^{(d)}}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\\
        \preceq & 2(1+\epsilon_d)\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\mathbf{x}}{\mathbf{x}}^\top\right]\\
        \preceq & 2(1+\epsilon_d)\sigma_0^2\mathbf{H},
    \end{aligned}
\end{equation}
where the second inequality holds by the definition of Example \ref{example G1} and the last inequality holds by Assumption \ref{assumption noise raw}. Regarding $\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\boldsymbol{\epsilon}^{(d)}\rangle^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]$,
\begin{equation}
\label{G10}
    \begin{aligned}
        &\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\boldsymbol{\epsilon}^{(d)}\rangle^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        =&\mathbb{E}\left[{\boldsymbol{\epsilon}^{(d)}}^\top{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \boldsymbol{\epsilon}^{(d)}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        \preceq & 2\mathbb{E}\left[{\boldsymbol{\epsilon}^{(d)}}^\top{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \boldsymbol{\epsilon}^{(d)}{\mathbf{x}}{\mathbf{x}}^\top\right]+2\mathbb{E}\left[{\boldsymbol{\epsilon}^{(d)}}^\top{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\\
        \preceq & 2\epsilon_d\alpha_0\mathrm{tr}({\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top\mathbf{H})\mathbf{H}+2\epsilon_d' \alpha_0\mathrm{tr}({\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top\mathbf{H})\mathbf{H},
    \end{aligned}
\end{equation}
where the last inequality holds by the definition of Example \ref{example G1} and Assumption \ref{ass2 raw data}. Regarding the term
\begin{equation}
\label{G11}
    \begin{aligned}
        \mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*- \mathbf{w}^*,\mathbf{x}\rangle^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\preceq &2\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*- \mathbf{w}^*,\mathbf{x}\rangle^2{\mathbf{x}}{\mathbf{x}}^\top\right]+2\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*- \mathbf{w}^*,\mathbf{x}\rangle^2{\boldsymbol{\epsilon}^{(d)}}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\\
        \preceq &2(1+\epsilon_d)\alpha_0 \mathrm{tr}\left(({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)^\top\mathbf{H}\right)\mathbf{H},
    \end{aligned}
\end{equation}
where the last inequality holds by the definition of Example \ref{example G1} and Assumption \ref{ass2 raw data}. Regarding $\mathbb{E}\left[(y^{(q)}-y)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]$, if we further assume that there exists a constant $C$ such that $\mathbb{E}\left[y^2 \mathbf{x}\mathbf{x}^\top\right]\preceq C\mathbf{H}$, then
\begin{equation}
\label{G12}
    \begin{aligned}
        \mathbb{E}\left[(y^{(q)}-y)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\preceq & 2\mathbb{E}\left[(y^{(q)}-y)^2{\mathbf{x}}{\mathbf{x}}^\top\right]+2\mathbb{E}\left[(y^{(q)}-y)^2{\boldsymbol{\epsilon}^{(d)}}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\\
        \preceq & 2(1+\epsilon_d)\mathbb{E}\left[(y^{(q)}-y)^2\mathbf{x}\mathbf{x}^\top\right]\\
        = & 2(1+\epsilon_d)\epsilon_l \mathbb{E}[y^2\mathbf{x}\mathbf{x}^\top]\\
        \preceq & 2(1+\epsilon_d)\epsilon_lC\mathbf{H}.
    \end{aligned}
\end{equation}

Therefore, together with (\ref{G8}), (\ref{G9}), (\ref{G10}), (\ref{G11}) and (\ref{G12}), we have
\begin{equation*}
    \begin{aligned}
        &\mathbb{E}\left[(y^{(q)}-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x}^{(q)}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        \precsim & (1+\epsilon_d)\sigma_0^2\mathbf{H}+(\epsilon_d+\epsilon_d')\alpha_0\left\|{\mathbf{w}^{(q)}}^*\right\|_\mathbf{H}^2\mathbf{H}
        +(1+\epsilon_d)\alpha_0\left\|{\mathbf{w}^{(q)}}^*- \mathbf{w}^*\right\|_\mathbf{H}^2\mathbf{H}+(1+\epsilon_d)\epsilon_l\mathbf{H}\\
        \precsim& \left[(1+\epsilon_d)(\sigma_0^2+\epsilon_l)+(1+\epsilon_d+\epsilon_d')\alpha_0\|\mathbf{w}^*\|_\mathbf{H}^2\right]\mathbf{H}\\
        =&\left(\sigma_0^2+\epsilon_l+\frac{1+\epsilon_d+\epsilon_d'}{1+\epsilon_d}\alpha_0\|\mathbf{w}^*\|_\mathbf{H}^2\right)\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}
That is, under strong multiplicative quantization Example \ref{example G1} and fourth moment Assumption \ref{assumption noise raw} on full-precision data, Assumption \ref{ass3} is verified.

Under strong additive quantization \ref{exampleG2}, Assumption \ref{ass2 raw data} and Assumption \ref{assumption noise raw},
\begin{equation*}
    \begin{aligned}
        \mathbb{E}\left[(y^{(q)}-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x}^{(q)}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]
        \precsim\left[\sigma_0^2+\epsilon_l+\epsilon_d(1+\frac{\epsilon_d'}{\epsilon_d^2})\left\|{\mathbf{w}}^*\right\|^2+(1+\alpha_0)\left\|{\mathbf{w}}^*\right\|_\mathbf{H}^2\right]\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

Regarding $\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]$, if we further assume that $\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2\right]\leq \sigma_0^2$, then
\begin{equation}
\label{G13}
    \begin{aligned}
        \mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right] \preceq& 2\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\mathbf{x}}{\mathbf{x}}^\top\right]+2\mathbb{E}\left[(y-\langle \mathbf{w}^*,\mathbf{x}\rangle)^2{\boldsymbol{\epsilon}^{(d)}}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\\
        \preceq & 2\sigma_0^2 \mathbf{H}+2\epsilon_d\sigma_0^2  \mathbf{I}.
    \end{aligned}
\end{equation}
Regarding $\mathbb{E}\left[(y^{(q)}-y)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]$,
\begin{equation}
\label{G14}
    \mathbb{E}\left[(y^{(q)}-y)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right] \leq \epsilon_d\epsilon_l\mathbf{I}.
\end{equation}
Regarding $\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\boldsymbol{\epsilon}^{(d)}\rangle^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]$,
\begin{equation}
\label{G15}
    \begin{aligned}
        &\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*,\boldsymbol{\epsilon}^{(d)}\rangle^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        =&\mathbb{E}\left[{\boldsymbol{\epsilon}^{(d)}}^\top{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \boldsymbol{\epsilon}^{(d)}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        \preceq & 2\mathbb{E}\left[{\boldsymbol{\epsilon}^{(d)}}^\top{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \boldsymbol{\epsilon}^{(d)}{\mathbf{x}}{\mathbf{x}}^\top\right]+2\mathbb{E}\left[{\boldsymbol{\epsilon}^{(d)}}^\top{\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top \boldsymbol{\epsilon}^{(d)}{\boldsymbol{\epsilon}^{(d)}}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\\
        \preceq & 2\epsilon_d\mathrm{tr}({\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top)\mathbf{H}+2\epsilon_d' \mathrm{tr}({\mathbf{w}^{(q)}}^*{{\mathbf{w}^{(q)}}^*}^\top)\mathbf{I}.
    \end{aligned}
\end{equation}
Regarding $\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*- \mathbf{w}^*,\mathbf{x}\rangle^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]$,
\begin{equation}
\label{G16}
    \begin{aligned}
        &\mathbb{E}\left[\langle {\mathbf{w}^{(q)}}^*- \mathbf{w}^*,\mathbf{x}\rangle^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        =&\mathbb{E}\left[\mathbf{x}^\top ({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)^\top\mathbf{x}{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        \preceq & 2\mathbb{E}\left[\mathbf{x}^\top ({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)^\top\mathbf{x}{\mathbf{x}}{\mathbf{x}}^\top\right]+2\mathbb{E}\left[\mathbf{x}^\top ({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)^\top\mathbf{x}{\boldsymbol{\epsilon}^{(d)}}{\boldsymbol{\epsilon}^{(d)}}^\top\right]\\
        \preceq& 2\alpha_0\mathrm{tr}\left(({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)^\top\mathbf{H}\right)\mathbf{H}+2\epsilon_d\mathrm{tr}\left(({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)({\mathbf{w}^{(q)}}^*- \mathbf{w}^*)^\top\mathbf{H}\right)\mathbf{I}.
    \end{aligned}
\end{equation}

Therefore, together with (\ref{G8}), (\ref{G13}), (\ref{G14}), (\ref{G15}) and (\ref{G16}), we have
\begin{equation*}
    \begin{aligned}
        &\mathbb{E}\left[(y^{(q)}-\langle {\mathbf{w}^{(q)}}^*,\mathbf{x}^{(q)}\rangle)^2{\mathbf{x}^{(q)}}{\mathbf{x}^{(q)}}^\top\right]\\
        \precsim &(\sigma_0^2+\epsilon_l)\mathbf{H}^{(q)}+\epsilon_d(1+\frac{\epsilon_d'}{\epsilon_d^2})\left\|{\mathbf{w}^{(q)}}^*\right\|^2\mathbf{H}^{(q)}+(1+\alpha_0)\left\|{\mathbf{w}^{(q)}}^*-\mathbf{w}^*\right\|_\mathbf{H}^2\mathbf{H}^{(q)}\\
        \leq& \left[\sigma_0^2+\epsilon_l+\epsilon_d(1+\frac{\epsilon_d'}{\epsilon_d^2})\left\|{\mathbf{w}}^*\right\|^2+(1+\alpha_0)\left\|{\mathbf{w}}^*\right\|_\mathbf{H}^2\right]\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}
That is, under strong additive quantization Example \ref{exampleG2} and noise Assumption \ref{assumption noise raw} on full-precision data, Assumption \ref{ass3} is verified.

\label{update rule for eta_t^2, master}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3},
\begin{equation*}
    \mathbb{E}\left[\boldsymbol{\eta}_t\boldsymbol{\eta}_t^\top\right]\preceq 2(\mathbf{B}_t+\mathbf{C}_t),
\end{equation*}
where
\begin{gather*}
        \mathbf{C}_t
        \preceq \mathbb{E}\left[\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]+\gamma^2 {\sigma_G^{(q)}}^2\mathbf{H}^{(q)}+2\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right],\\
        \mathbf{B}_t
        = \mathbb{E}\left[\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{B}_{t-1}\left(\mathbf{I}-\gamma\frac{1}{B} {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right],
\end{gather*}
with $\mathbf{C}_0=\boldsymbol{0},\ \mathbf{B}_0=\mathbb{E}\left[\boldsymbol{\eta}_0\boldsymbol{\eta}_0^\top\right]$ and
\begin{equation*}
    \begin{aligned}
        {\sigma_G^{(q)}}^2=&\frac{\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}\\
        +&2\alpha_B\sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]
        +\frac{\sigma^2}{B},
    \end{aligned}
\end{equation*}

Noticing that
\begin{equation}
    \label{eq: F3}
    \begin{aligned}
        &\mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\right)\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X}_t)}^\top \mathcal{Q}_d(\mathbf{X}_t)\right)\right]\\
        \preceq&2\frac{\gamma^2}{B^2}\mathbb{E}\left[{\mathcal{Q}_d(\mathbf{X}_t)}^\top {\mathcal{Q}_d(\mathbf{X}_t)}\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top {\mathcal{Q}_d(\mathbf{X}_t)}^\top\mathcal{Q}_d(\mathbf{X}_t)\right]+2\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right],
    \end{aligned}
\end{equation}
together with (\ref{eq: F2}) and Lemma \ref{update rule for eta_t^2}, we complete the proof.

\label{update rule for eta_t^2 multiplicative, master}
If there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative, then under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, it holds
\begin{equation*}
    \mathbb{E}\left[\boldsymbol{\eta}_t\boldsymbol{\eta}_t^\top\right]\preceq 2(\mathbf{B}_t+\mathbf{C}_t),
\end{equation*}
where
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_t
        \preceq&\mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{C}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right]+8\epsilon_p\left(\mathbf{C}_{t-1}+\mathbf{B}_{t-1}\right)\\
        +&\tilde{\epsilon}\mathbb{E}\left[\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top {\mathcal{Q}_d(\mathbf{X})}(\mathbf{B}_{t-1}+\mathbf{C}_{t-1})\frac{\gamma}{B}{\mathcal{Q}_d(\mathbf{X})}^\top\mathcal{Q}_d(\mathbf{X})\right]
        +\gamma^2 {\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+4\epsilon_p{\mathbf{w}^{(q)}}^*({\mathbf{w}^{(q)}}^*)^\top,\\
        \mathbf{B}_t=& \mathbb{E}\left[\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\mathbf{B}_{t-1}\left(\mathbf{I}-\frac{1}{B}\gamma {\mathcal{Q}_d(\mathbf{X})}^\top \mathcal{Q}_d(\mathbf{X}) \right)\right],
    \end{aligned}
\end{equation*}
with
\begin{gather*}
        \tilde{\epsilon}=8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+8\epsilon_p+4\epsilon_a(1+\epsilon_p),\\
        {\sigma_M^{(q)}}^2=\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+4\epsilon_p \right).
\end{gather*}

Under multiplicative quantization,
\begin{equation}
    \label{eq: ffds}
    \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]=\epsilon_p\mathbb{E}\left[\mathbf{w}_{t-1}\mathbf{w}_{t-1}^\top\right]\preceq2\epsilon_p\mathbb{E}\left[\boldsymbol{\eta}_{t-1}\boldsymbol{\eta}_{t-1}^\top\right]+2\epsilon_p{\mathbf{w}^{(q)}}^*({\mathbf{w}^{(q)}}^*)^\top.
\end{equation}
By (\ref{eq: F2}), (\ref{eq: F3}), (\ref{eq: ffds}) and Lemma \ref{update rule for eta_t^2 multiplicative},
the proof is immediately completed.

\label{A bound for M_B^{(q)} C_t, master}
For $t \geq 1$, under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize $\gamma \leq \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t \preceq \frac{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\left(\gamma{\sigma_G^{(q)}}^2+\frac{2d\mu}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}\right)}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}.
\end{equation*}

We first derive a crude bound for $\mathbf{C}_t$. Denote $\boldsymbol{\Sigma}={\sigma_G^{(q)}}^2\mathbf{H}^{(q)}+\frac{2}{\gamma^2}\sup_t\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]$. By (\ref{solution of Cinfty}),
\begin{equation*}
    \mathbf{C}_t \preceq \mathbf{C}_\infty=\gamma{\mathcal{T}_B^{(q)}}^{-1}\circ\mathbf{\Sigma}.
\end{equation*}
Applying $\widetilde{\mathcal{T}}^{(q)}$, we have
\begin{equation*}
        \begin{aligned}
            \widetilde{\mathcal{T}}^{(q)}\circ\mathbf{C}_{\infty} & =\mathcal{T}_B^{(q)}\circ\mathbf{C}_{\infty}+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_{\infty}-\gamma\widetilde{\mathcal{M}}^{(q)}\circ\mathbf{C}_{\infty} \\
            & =\gamma\boldsymbol{\Sigma}+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty-\gamma\widetilde{\mathcal{M}}^{(q)}\circ\mathbf{C}_\infty\\
            & \preceq\gamma\boldsymbol{\Sigma}+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty\\
            &=\gamma{\sigma_G^{(q)}}^2\mathbf{H}^{(q)}+\frac{2}{\gamma}\sup_t\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]+\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty.
        \end{aligned}
\end{equation*}
Applying $(\widetilde{\mathcal{T}}^{(q)})^{-1}$ and by solving recursion, we have
\begin{equation}
    \label{eq: f4}
    \begin{aligned}
        \mathbf{C}_\infty& \preceq \gamma{\sigma_G^{(q)}}^2(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}+\frac{2}{\gamma}(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\sup_t\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]+\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty\\
        & \preceq\sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ\left(\gamma{\sigma_G^{(q)}}^2(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}+\frac{2}{\gamma}(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\sup_t\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]\right).
    \end{aligned}
\end{equation}
By (\ref{eq: c26}),
\begin{equation}
    \label{eq: f5}
    \sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ\gamma{\sigma_G^{(q)}}^2(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbf{H}^{(q)}\preceq \frac{\gamma{\sigma_G^{(q)}}^2}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{I}.
\end{equation}
Noticing that
\begin{equation*}
    \begin{aligned}
        (\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\sup_t\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]=&\gamma\sum_{t=0}^\infty(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^t\circ\sup_t\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right] \\
        =&\gamma\sum_{t=0}^\infty(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\sup_t\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right](\mathbf{I}- \gamma\mathbf{H}^{(q)})^t \\
        \preceq& \sup_t\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]\right\| (\mathbf{H}^{(q)})^{-1}:=\mu\cdot(\mathbf{H}^{(q)})^{-1},
    \end{aligned}
\end{equation*}
we have
\begin{equation}
    \label{eq: f6}
    \begin{aligned}
        &\sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ\frac{2}{\gamma}(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]\\
        =&\sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ\frac{2\mu}{\gamma}(\mathbf{H}^{(q)})^{-1}\\
        =&\sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^{t-1}\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ\frac{2\mu}{\gamma}(\mathbf{H}^{(q)})^{-1}\\
        \preceq&\sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^{t-1}\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\alpha_B\mathrm{tr}(\mathbf{I})\frac{2\mu}{\gamma}\mathbf{H}^{(q)}\\
        \preceq&\sum_{t=0}^\infty\left(\gamma(\widetilde{\mathcal{T}}^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^{t-1}2\mu\alpha_Bd\cdot\mathbf{I}\\
        \preceq&2d\mu \alpha_B \cdot \sum_{t=0}^\infty \left(\gamma \alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\right)^{t-1}\mathbf{I}\\
        =&\frac{2d\mu}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})} \cdot \sum_{t=0}^\infty \left(\gamma \alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\right)^{t}\mathbf{I}\\
        =&\frac{2d\mu}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})} \frac{1}{1-\gamma\alpha_B\mathrm{tr}\left(\mathbf{H}^{(q)}\right)}\mathbf{I}.
    \end{aligned}
\end{equation}

Therefore, together with (\ref{eq: f4}), (\ref{eq: f5}) and (\ref{eq: f6}), we have
\begin{equation*}
    \mathbf{C}_t\preceq\mathbf{C}_\infty\preceq \frac{\gamma{\sigma_G^{(q)}}^2+\frac{2d\mu}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{I}.
\end{equation*}
It follows that
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t \preceq \frac{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\left(\gamma{\sigma_G^{(q)}}^2+\frac{2d\mu}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}\right)}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}.
\end{equation*}

\label{variance R2 bound, master}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\begin{equation*}
    \mathrm{variance}\leq \frac{{\sigma_G^{(q)}}^2+\frac{2\alpha_Bd\mu}{\gamma}}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right)+\frac{2\mu}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right),
\end{equation*}
where $\mu=\sup_t\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]\right\|$.

We first provide a refined upper bound for $\mathbf{C}_t$. By (\ref{eq: ff}) and Lemma \ref{A bound for M_B^{(q)} C_t, master},
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_t \preceq &(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1}+\gamma^2\mathcal{M}_B^{(q)}\circ \mathbf{C}_{t-1}+\gamma^2{\sigma_G^{(q)}}^2\mathbf{H}^{(q)}+2\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]\\
        \preceq & (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1} + \frac{\gamma^2\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\left(\gamma{\sigma_G^{(q)}}^2+\frac{2d\mu}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}\right)}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}+\gamma^2{\sigma_G^{(q)}}^2\mathbf{H}^{(q)}+2\mu\mathbf{I}\\
        =& (\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})\circ \mathbf{C}_{t-1} + \frac{\gamma^2{\sigma_G^{(q)}}^2+2\gamma\alpha_Bd\mu}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})} \mathbf{H}^{(q)}+2\mu\mathbf{I}\\
        =&\frac{\gamma^2{\sigma_G^{(q)}}^2+2\gamma\alpha_Bd\mu}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^k\circ\mathbf{H}^{(q)}+2\mu\sum_{k=0}^{t-1}(\mathcal{I}-\gamma\widetilde{\mathcal{T}}^{(q)})^k\circ\mathbf{I}\\
        =&\frac{\gamma^2{\sigma_G^{(q)}}^2+2\gamma\alpha_Bd\mu}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\sum_{k=0}^{t-1}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^k\mathbf{H}^{(q)}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^k+2\mu\sum_{k=0}^{t-1}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^{2k} \\
        \preceq&\frac{\gamma^2{\sigma_G^{(q)}}^2+2\gamma\alpha_Bd\mu}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\sum_{k=0}^{t-1}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^k\mathbf{H}^{(q)}+2\mu\sum_{k=0}^{t-1}(\mathbf{I}-\gamma \mathbf{H}^{(q)})^{k} \\
        =&\underbrace{\frac{\gamma{\sigma_G^{(q)}}^2+2\alpha_Bd\mu}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\cdot\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\right)}_{\mathbf{V}_1}+\underbrace{\frac{2\mu}{\gamma}\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\right)(\mathbf{H}^{(q)})^{-1}}_{\mathbf{V}_2}.
    \end{aligned}
\end{equation*}
By (\ref{eq: c31}),
\begin{equation}
    \label{eq: f8}
    \begin{aligned}
        \frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{V}_1\right\rangle\leq\frac{{\sigma_G^{(q)}}^2+\frac{2\alpha_Bd\mu}{\gamma}}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
    \end{aligned}
\end{equation}
Regarding $\mathbf{V}_2$,
\begin{equation}
    \label{eq: f9}
    \begin{aligned}
        &\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{V}_2\right\rangle\\
        =&\frac{2\mu}{\gamma^2 N^2}\cdot\sum_{t=0}^{N-1}\left\langle\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N-t},\left(\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^t\right)(\mathbf{H}^{(q)})^{-1}\right\rangle\\
        =&\frac{2\mu}{\gamma^2 N^2}\sum_i\sum_{t=0}^{N-1}\left[1-(1-\gamma\lambda_i^{(q)})^{N-t}\right]\left[1-(1-\gamma\lambda_i^{(q)})^t\right]\frac{1}{\lambda_i^{(q)}}\\
        \leq &\frac{2\mu}{\gamma^2 N}\sum_i \min\left\{\frac{1}{\lambda_i^{(q)}},\gamma^2 N^2\lambda_i^{(q)}\right\}\\
        \leq&\frac{2\mu}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right).
    \end{aligned}
\end{equation}
Together with (\ref{eq: f}), (\ref{eq: f8}) and (\ref{eq: f9}), we have
\begin{equation*}
    \mathrm{variance}\leq \frac{{\sigma_G^{(q)}}^2+\frac{2\alpha_Bd\mu}{\gamma}}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right)+2\frac{\mu}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right),
\end{equation*}
where $\mu=\sup_t\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]\right\|$.

\label{thm: master general}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}$, then
\begin{equation*}
    \begin{aligned}
        R_N^{(0)}/2 \leq &\frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
        +& \frac{{\sigma_G^{(q)}}^2+\frac{2\alpha_Bd\mu}{\gamma}}{1-\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right)+\frac{2\mu}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right),
    \end{aligned}
\end{equation*}
where $k^*=\max\left\{k: \lambda_k^{(q)} \geq \frac{1}{N\gamma}\right\}$, $\mu=\sup_t\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top\right]\right\|$ and
\begin{gather*}
    {\sigma_G^{(q)}}^2=\frac{\sup_t \left\{\left\|\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(o)}{\boldsymbol{\epsilon}_t^{(o)}}^\top|\mathbf{o}_t\right]+\mathbb{E}\left[\boldsymbol{\epsilon}_t^{(a)}{\boldsymbol{\epsilon}_t^{(a)}}^\top|\mathbf{a}_t\right] \right\|\right\}}{B}\\
    +2\alpha_B\sup_t\mathbb{E}_{\mathbf{w}_{t-1}}\left[\mathrm{tr}\left(\mathbf{H}^{(q)} \mathbb{E}\left[\boldsymbol{\epsilon}_{t-1}^{(p)}{\boldsymbol{\epsilon}_{t-1}^{(p)}}^\top \big| \mathbf{w}_{t-1}\right]\right)\right]
    +\frac{\sigma^2}{B}.
\end{gather*}

\label{thm: master additive}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-additive, if the stepsize satisfies $\gamma < \frac{1}{\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}$, then
\begin{equation*}
    \begin{aligned}
        R_N^{(0)}/2 \leq &\frac{2\alpha_B\left(\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{I}_{0:k^*}^{(q)}}^2+N\gamma\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\right)}{N\gamma(1-\gamma\alpha_B[\operatorname{tr}(\mathbf{H})+d\epsilon_d])}\cdot\left(\frac{k^*}{N}+N\gamma^2\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right)\\
        +& \frac{1}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{k^*:\infty}^{(q)}}^2\\
        +& \frac{\frac{\sigma^2+\epsilon_o+\epsilon_a}{B}+2\epsilon_p\alpha_B\left(\frac{d}{\gamma}+\mathrm{tr}(\mathbf{H})+d\epsilon_d\right)}{1-\gamma\alpha_B[\mathrm{tr}(\mathbf{H})+d\epsilon_d]}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i+\epsilon_d)^2\right)\\
        +&\frac{2\epsilon_p}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma(\lambda_i+\epsilon
        _d)}+N\gamma\sum_{i>k^*}(\lambda_i+\epsilon
        _d)\right).
    \end{aligned}
\end{equation*}

\label{A bound for M_B^{(q)} C_t^{(M)}, master}
For $t \geq 1$, under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the step size satisfies
\begin{equation*}
    1>2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)}),\quad 8\epsilon_p\leq \gamma \lambda_d^{(q)}-\frac{3}{4}\gamma^2{\lambda_d^{(q)}}^2,
\end{equation*}
then
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t^{(M)} \preceq\frac{2\gamma{\sigma_M^{(q)}}^2+\frac{8d\epsilon_p}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}.
\end{equation*}

By (\ref{initial CtM, master}),
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_t^{(M)}\preceq \mathbf{C}_\infty^{(M)}\preceq \gamma\left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-\gamma(1+\widetilde{\epsilon})\mathcal{M}_B^{(q)}\right)^{-1}\circ\underbrace{\left({\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+4\frac{\epsilon_p}{\gamma^2}\mathbf{I}\right)}_{\boldsymbol{\Sigma}}.
    \end{aligned}
\end{equation*}
Applying $\widetilde{\mathcal{T}}_2^{(q)}$,
\begin{equation*}
    \begin{aligned}
        \widetilde{\mathcal{T}}_2^{(q)}\circ\mathbf{C}_\infty^{(M)} & =(\widetilde{\mathcal{T}}_2^{(q)}-2(1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)})\circ\mathbf{C}_\infty^{(M)}+2(1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty^{(M)} \\
        & \preceq2\gamma\boldsymbol{\Sigma}+2(1+\tilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty^{(M)}.
    \end{aligned}
\end{equation*}
Applying $(\widetilde{\mathcal{T}}_2^{(q)})^{-1}$ we have
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_{\infty}^{(M)}  \preceq&2\gamma{\sigma_M^{(q)}}^2\cdot(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathbf{H}^{(q)}+\frac{8\epsilon_p}{\gamma}(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathbf{I}
        +2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ\mathbf{C}_\infty^{(M)}\\
        \preceq&\sum_{t=0}^\infty\left(2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\left(2\gamma{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+\frac{8\epsilon_p}{\gamma}\mathbf{I}\right).
    \end{aligned}
\end{equation*}
Noticing that $(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathbf{H}^{(q)}  \preceq \mathbf{I}$ and $(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathbf{I}\preceq  (\mathbf{H}^{(q)})^{-1}$,
we have
\begin{equation}
    \label{eq: f13}
    \begin{aligned}
        \mathbf{C}_{\infty}^{(M)}\preceq&\sum_{t=0}^\infty\left(2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\left(2\gamma{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+\frac{8\epsilon_p}{\gamma}\mathbf{I}\right)\\
        \preceq&\sum_{t=0}^\infty\left(2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^t\circ\left(2\gamma{\sigma_M^{(q)}}^2\mathbf{I}+\frac{8\epsilon_p}{\gamma}(\mathbf{H}^{(q)})^{-1}\right).
    \end{aligned}
\end{equation}
Firstly,
\begin{equation}
    \label{eq: f14}
    \begin{aligned}
        2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ \mathbf{I}\preceq &2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\mathbf{I}.
    \end{aligned}
\end{equation}
Secondly,
\begin{equation}
    \label{eq: f15}
    \begin{aligned}
        2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\circ (\mathbf{H}^{(q)})^{-1}\preceq&2(1+\tilde{\epsilon})\gamma\alpha_B \mathrm{tr}(\mathbf{I})\mathbf{I}.
    \end{aligned}
\end{equation}

Therefore, together with (\ref{eq: f13}), (\ref{eq: f14}) and (\ref{eq: f15}), we have
\begin{equation*}
    \begin{aligned}
        \mathbf{C}_{\infty}^{(M)}\preceq&\sum_{t=0}^\infty\left(2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^{t-1}\circ \mathbf{I}
        \cdot\left[4(1+\tilde{\epsilon})\gamma^2{\sigma_{M}^{(q)}}^2\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})+16(1+\tilde{\epsilon})\alpha_B d\epsilon_p\right]\\
        =&\left(2\gamma{\sigma_M^{(q)}}^2+\frac{8d\epsilon_p}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}\right) \sum_{t=0}^\infty\left(2(1+\tilde{\epsilon})\gamma(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathcal{M}_B^{(q)}\right)^{t-1}\circ \mathbf{I}\cdot2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\\
        \preceq&\left(2\gamma{\sigma_M^{(q)}}^2+\frac{8d\epsilon_p}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}\right) \sum_{t=0}^\infty\left[2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\right]^{t} \mathbf{I}\\
        =&\frac{2\gamma{\sigma_M^{(q)}}^2+\frac{8d\epsilon_p}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{I},
    \end{aligned}
\end{equation*}
where the second inequality uses (\ref{eq: f14}). At last,
\begin{equation*}
    \mathcal{M}_B^{(q)} \circ \mathbf{C}_t^{(M)} \preceq\frac{2\gamma{\sigma_M^{(q)}}^2+\frac{8d\epsilon_p}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}.
\end{equation*}

\label{lem: f6}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the step size satisfies
\begin{equation*}
    1>2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)}),\quad 8\epsilon_p\leq \gamma \lambda_d^{(q)}-\frac{3}{4}\gamma^2{\lambda_d^{(q)}}^2,
\end{equation*}
then
\begin{equation*}
    \begin{aligned}
        \mathbb{E}_{\mathbf{w}^*}\mathrm{variance}\leq &\frac{4{\sigma_M^{(q)}}^2+32(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B/\gamma}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +
        &\frac{16\epsilon_p}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right).
    \end{aligned}
\end{equation*}

We first provide a refined upper bound for $\mathbf{C}_t$. 
By (\ref{initial CtM, master}) and Lemma \ref{A bound for M_B^{(q)} C_t^{(M)}, master},
\begin{equation}
    \label{eq: f17}
    \begin{aligned}
        \mathbf{C}_t^{(M)}\preceq&(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})\circ \mathbf{C}_{t-1}^{(M)}+\gamma^2(1+\tilde{\epsilon})\mathcal{M}_B^{(q)}\circ \mathbf{C}_{t-1}^{(M)}
        +\gamma^2{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+4\epsilon_p\mathbf{I}\\
        \preceq&(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})\circ \mathbf{C}_{t-1}^{(M)}
        +\gamma^2{\sigma_M^{(q)}}^2\mathbf{H}^{(q)}+4\epsilon_p\mathbf{I}\\
        +&\gamma^2(1+\tilde{\epsilon})\frac{2\gamma{\sigma_M^{(q)}}^2+\frac{8d\epsilon_p}{\gamma\mathrm{tr}(\mathbf{H}^{(q)})}}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}\\
        =&(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})\circ \mathbf{C}_{t-1}^{(M)}+\frac{\gamma^2{\sigma_M^{(q)}}^2+8\gamma(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{H}^{(q)}+4\epsilon_p\mathbf{I}\\
        =&\frac{\gamma^2{\sigma_M^{(q)}}^2+8\gamma(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_{k=0}^{t-1}(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^k\circ\mathbf{H}^{(q)}+4\epsilon_p\sum_{k=0}^{t-1}(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^k\circ\mathbf{I}\\
        \preceq&\frac{\gamma^2{\sigma_M^{(q)}}^2+8\gamma(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_{k=0}^{t-1}(\mathbf{I}-\frac{\gamma}{2} \mathbf{H}^{(q)})^{k}\mathbf{H}^{(q)}+4\epsilon_p\sum_{k=0}^{t-1}(\mathbf{I}-\frac{\gamma}{2} \mathbf{H}^{(q)})^{k}\\
        =&\underbrace{\frac{2\gamma{\sigma_M^{(q)}}^2+16(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}(\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2} \mathbf{H}^{(q)})^{t})}_{\mathbf{V}_1}+\underbrace{\frac{8\epsilon_p}{\gamma}(\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2} \mathbf{H}^{(q)})^{t})(\mathbf{H}^{(q)})^{-1}}_{\mathbf{V}_2}.
    \end{aligned}
\end{equation}

Recall (\ref{eq: f mul}),
\begin{equation*}
    \mathbb{E}_{\mathbf{w}^*}\mathrm{variance}\leq\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{V}_1+\mathbf{V}_2\right\rangle.
\end{equation*}
Regarding $\mathbf{V}_1$, 
\begin{equation}
\label{eq: f18}
    \begin{aligned}
        &\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{V}_1\right\rangle\\
        \leq&\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{V}_1\right\rangle\\
        \leq&\frac{2}{N^2\gamma}\frac{2\gamma{\sigma_M^{(q)}}^2+16(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_{t=0}^{N-1}\left\langle\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N-t},\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2} \mathbf{H}^{(q)})^{t}\right\rangle\\
        =&\frac{2}{N^2\gamma}\frac{2\gamma{\sigma_M^{(q)}}^2+16(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_{t=0}^{N-1}\sum_i(1-(1-\frac{\gamma}{2}\lambda_i^{(q)})^{N-t})(1-(1-\frac{\gamma}{2} \lambda_i^{(q)})^{t})\\
        \leq&\frac{2}{N^2\gamma}\frac{2\gamma{\sigma_M^{(q)}}^2+16(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_{t=0}^{N-1}\sum_i\left[1-(1-\frac{\gamma}{2}\lambda_i^{(q)})^{N}\right]^2\\
        \leq&\frac{2}{N\gamma}\frac{2\gamma{\sigma_M^{(q)}}^2+16(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_i\min\left\{1,\frac{\gamma^2N^2}{4}{\lambda_i^{(q)}}^2\right\}\\
        \leq&\frac{2}{N\gamma}\frac{2\gamma{\sigma_M^{(q)}}^2+16(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\sum_i\min\left\{1,{\gamma^2N^2}{\lambda_i^{(q)}}^2\right\}\\
        =&\frac{4{\sigma_M^{(q)}}^2+32(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B/\gamma}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right).
    \end{aligned}
\end{equation}

Regarding $\mathbf{V}_2$,
\begin{equation}
    \label{eq: f19}
    \begin{aligned}
        &\frac{1}{N^2}\cdot\sum_{t=0}^{N-1}\sum_{k=t}^{N-1}\left\langle(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{k-t}\mathbf{H}^{(q)},\mathbf{V}_2\right\rangle\\
        \leq&\frac{2}{N^2\gamma}\cdot\sum_{t=0}^{N-1}\left\langle\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N-t},\mathbf{V}_2\right\rangle\\
        =&\frac{8\epsilon_p}{\gamma}\frac{2}{N^2\gamma}\cdot\sum_{t=0}^{N-1}\left\langle\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N-t},(\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2} \mathbf{H}^{(q)})^{t})(\mathbf{H}^{(q)})^{-1}\right\rangle\\
        =&\frac{8\epsilon_p}{\gamma}\frac{2}{N^2\gamma}\cdot\sum_{t=0}^{N-1}\sum_i\left[1-(1-\frac{\gamma}{2}\lambda_i^{(q)})^{N-t}\right]\left[1-(1-\frac{\gamma}{2}\lambda_i^{(q)})^t\right]\frac{1}{\lambda_i^{(q)}}\\
        \leq&\frac{16\epsilon_p}{N\gamma^2}\sum_i\min\left\{ \frac{1}{\lambda_i^{(q)}}, N^2\gamma^2{\lambda_i^{(q)}}\right\}\\
        =&\frac{16\epsilon_p}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right).
    \end{aligned}
\end{equation}

Together with (\ref{eq: f mul}), (\ref{eq: f17}), (\ref{eq: f18}) and (\ref{eq: f19}),
\begin{gather*}
    \mathbb{E}_{\mathbf{w}^*}\mathrm{variance}\leq \frac{4{\sigma_M^{(q)}}^2+32(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B/\gamma}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right)+\frac{16\epsilon_p}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right).
\end{gather*}

\label{lem: f7}
For $1 \leq t\leq N$, under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the step size satisfies
\begin{equation*}
    1>2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)}),\quad 8\epsilon_p\leq \gamma \lambda_d^{(q)}-\frac{3}{4}\gamma^2{\lambda_d^{(q)}}^2,
\end{equation*}
then
\begin{equation*}
     \mathcal{M}_B^{(q)} \circ \mathbf{S}_t^{(M)} \preceq          \frac{2\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^t\right]\circ\mathbf{B}_0\right)}{\gamma(1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}.
\end{equation*}

From (\ref{eq: f20}),
\begin{equation*}
    \begin{aligned}
        \mathbf{S}_t^{(M)}\preceq& \sum_{k=0}^{t-1}\left(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)}+(1+\widetilde{\epsilon})\gamma^2\mathcal{M}_B^{(q)}\right)^k\circ \mathbf{B}_0\\
        =&\frac{1}{\gamma}\left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\underbrace{\left[\mathcal{I}-\left(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)}+(1+\widetilde{\epsilon})\gamma^2\mathcal{M}_B^{(q)}\right)^t\right]\circ \mathbf{B}_0}_{\mathbf{A}}.
    \end{aligned}
\end{equation*}
Applying $\widetilde{\mathcal{T}}_2^{(q)}$, we have
\begin{equation*}
    \begin{aligned}
        &\widetilde{\mathcal{T}}_2^{(q)}\circ\left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}\\
        =&2\mathbf{A}+2(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ \left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}.
    \end{aligned}
\end{equation*}
Applying $(\widetilde{\mathcal{T}}_2^{(q)})^{-1}$, we have
\begin{equation*}
    \begin{aligned}
        &\left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}\\
        =&2(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ \mathbf{A}+2(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ (1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ \left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}.
    \end{aligned}
\end{equation*}
Applying $\mathcal{M}_B^{(q)}$, we have
\begin{equation*}
    \begin{aligned}
        &\mathcal{M}_B^{(q)}\circ \left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}\\
        =&2\mathcal{M}_B^{(q)}\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ (1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ \left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}+2\mathcal{M}_B^{(q)}\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ \mathbf{A}.
    \end{aligned}
\end{equation*}
It follows that
\begin{equation}
    \label{eq: f21}
    \begin{aligned}
        &\mathcal{M}_B^{(q)}\circ \left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}\\
        =&\sum_{t=0}^\infty \left(2(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\right)^t\circ 2\mathcal{M}_B^{(q)}\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ \mathbf{A}.
    \end{aligned}
\end{equation}
By Assumption \ref{ass2}, 
\begin{equation*}
    \begin{aligned}
        {\mathcal{M}_B^{(q)}}\circ{(\widetilde{\mathcal{T}}_2^{(q)})}^{-1}\circ\mathbf{A}&\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}{(\widetilde{\mathcal{T}}_2^{(q)})}^{-1}\circ\mathbf{A})\mathbf{H}^{(q)}\\
        &= \alpha_B \frac{\gamma}{2}\operatorname{tr}\left(\sum_{t=0}^{\infty}\mathbf{H}^{(q)}(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{t}\mathbf{A}(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{t}\right) \mathbf{H}^{(q)}\\
        &= \alpha_B \mathrm{tr}\left(\mathbf{H}^{(q)}(2\mathbf{H}^{(q)}-\frac{\gamma}{2}(\mathbf{H}^{(q)})^{2})^{-1}\mathbf{A}\right)\mathbf{H}^{(q)}\\
        &\preceq \alpha_B \mathrm{tr}(\mathbf{A})\mathbf{H}^{(q)},
    \end{aligned}
\end{equation*}
together with (\ref{eq: f21}), $(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\circ\mathbf{H}^{(q)}  \preceq \mathbf{I}$ and $\mathcal{M}_B^{(q)}\circ\mathbf{I}\preceq\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})\mathbf{H}^{(q)}$, we have
\begin{equation*}
    \begin{aligned}
        &\mathcal{M}_B^{(q)}\circ \left(\frac{1}{2}\widetilde{\mathcal{T}}_2^{(q)}-(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\right)^{-1}\circ\mathbf{A}\\
        \preceq&\sum_{t=0}^\infty \left(2(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\right)^t\circ 2\alpha_B\mathrm{tr}(\mathbf{A})\mathbf{H}^{(q)}\\
        =&2\alpha_B\mathrm{tr}(\mathbf{A})\sum_{t=0}^\infty \left(2(1+\widetilde{\epsilon})\gamma\mathcal{M}_B^{(q)}\circ(\widetilde{\mathcal{T}}_2^{(q)})^{-1}\right)^{t}\circ \mathbf{H}^{(q)}\\
        \preceq&2\alpha_B\mathrm{tr}(\mathbf{A})\sum_{t=0}^\infty \left(2(1+\widetilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})\right)^{t} \mathbf{H}^{(q)}\\
        =&\frac{2\alpha_B\mathrm{tr}(\mathbf{A})}{1-2(1+\widetilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

Therefore, recall that
\begin{equation*}
    \mathbf{A}=\left[\mathcal{I}-\left(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)}+(1+\widetilde{\epsilon})\gamma^2\mathcal{M}_B^{(q)}\right)^t\right]\circ \mathbf{B}_0\preceq\left[\mathcal{I}-\left(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)}\right)^t\right]\circ \mathbf{B}_0,
\end{equation*}
we have
\begin{equation*}
    \begin{aligned}
        \mathcal{M}_B^{(q)} \circ \mathbf{S}_t^{(M)} \preceq \gamma^{-1}\frac{2\alpha_B\operatorname{tr}(\mathbf{A})}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}\preceq \frac{2\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^t\right]\circ\mathbf{B}_0\right)}{\gamma(1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}.
    \end{aligned}
\end{equation*}

\label{bias R2 bound multiplicative, master}
Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the stepsize satisfies 
\begin{equation*}
    1>2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)}),\quad 8\epsilon_p\leq \gamma \lambda_d^{(q)}-\frac{3}{4}\gamma^2{\lambda_d^{(q)}}^2,
\end{equation*}
then
\begin{equation*}
    \begin{aligned}
        \mathrm{bias}
        \leq& \frac{8(1+\tilde{\epsilon})\alpha_B\cdot\left(\frac{\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{I}_{0:k^{*}}}^{2}}{N\gamma}+\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{H}_{k^{*}:\infty}}^{2}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N} + {N\gamma^2}\sum_{i> k^*}{\lambda_i^{(q)}}^2\right)\\
        +& \frac{4}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+4\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{{k^*}:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

By (\ref{eq: f20}) and Lemma \ref{lem: f7},
\begin{equation*}
    \begin{aligned}
        \mathbf{S}_{t}^{(M)}\preceq&(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+(1+\tilde{\epsilon})\gamma^{2}\mathcal{M}_B^{(q)}\circ\mathbf{S}_{t-1}^{(M)}+\mathbf{B}_{0}\\
        \preceq&(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})\circ\mathbf{S}_{t-1}^{(M)}+(1+\tilde{\epsilon})\gamma^{2}\frac{2\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^N\right]\circ\mathbf{B}_0\right)}{\gamma(1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\\
        =&\sum_{k=0}^{t-1}(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^k\circ\left((1+\tilde{\epsilon})\gamma^{2}\frac{2\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^N\right]\circ\mathbf{B}_0\right)}{\gamma(1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)\\
        =&\sum_{k=0}^{t-1}(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^k\left((1+\tilde{\epsilon})\gamma^{2}\frac{2\alpha_B\cdot\mathrm{tr}\left(\left[\mathcal{I}-(\mathcal{I}-\frac{\gamma}{2}\widetilde{\mathcal{T}}_2^{(q)})^N\right]\circ\mathbf{B}_0\right)}{\gamma(1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)}))}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^k.
    \end{aligned}
\end{equation*}

Before providing our upper bound for the bias error, we denote \begin{equation*}
    \mathbf{B}_{a,b}:=\mathbf{B}_a-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{b-a}\mathbf{B}_a(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{b-a}.
\end{equation*}
Recall from (\ref{eq: bias m}) that
\begin{equation*}
    \mathrm{bias}\leq \frac{1}{\gamma N^{2}}\left\langle\mathbf{I}-(\mathbf{I}-\gamma\mathbf{H}^{(q)})^{N},\sum_{t=0}^{N-1}\mathbf{B}_{t}^{(M)}\right\rangle,
\end{equation*}
we have
\begin{equation*}
    \begin{aligned}
        \mathrm{bias}\leq &\frac{2}{\gamma N^{2}}\left\langle\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N},\sum_{t=0}^{N-1}\mathbf{B}_{t}^{(M)}\right\rangle\\
        \leq&\frac{2}{\gamma N^{2}}\left\langle\mathbf{I}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N},\sum_{k=0}^{N-1}(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^k\left(\frac{2(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right)(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^k\right\rangle\\
        =&\frac{2}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{2k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+2k},\frac{2(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right\rangle.
    \end{aligned}
\end{equation*}
Note that 
\begin{equation*}
    \begin{aligned}
        (\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{2k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+2k}  \preceq(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+k},
    \end{aligned}
\end{equation*}
we have
\begin{equation*}
    \mathrm{bias}\leq \frac{2}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+k},\frac{2(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}+\mathbf{B}_{0}\right\rangle.
\end{equation*}

Therefore it suffices to bound the following two terms:
\begin{equation*}
    I_1=\frac{2}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+k},\frac{2(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\cdot\mathbf{H}^{(q)}\right\rangle,
\end{equation*}
\begin{equation*}
    I_2=\frac{2}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+k},\mathbf{B}_{0}\right\rangle.
\end{equation*}
Regarding $I_1$,
\begin{equation*}
    \begin{aligned}
        &\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+k},\mathbf{H}^{(q)}\right\rangle\\
        =&\sum_{k=0}^{N-1}\sum_i \left[(1-\frac{\gamma}{2}\lambda_i^{(q)})^k-(1-\frac{\gamma}{2}\lambda_i^{(q)})^{N+k}\right]\lambda_i^{(q)}\\
        =&\frac{2}{\gamma}\sum_i \left[[1-(1-\frac{\gamma}{2}\lambda_i^{(q)})^N]-[(1-\frac{\gamma}{2}\lambda_i^{(q)})^N-(1-\frac{\gamma}{2}\lambda_i^{(q)})^{2N}]\right]\\
        =&\frac{2}{\gamma}\sum_i \left(1-(1-\frac{\gamma}{2}\lambda_i^{(q)})^N\right)^2\\
        \leq&\frac{2}{\gamma}\sum_i \min\left\{1, {N^2\gamma^2}{\lambda_i^{(q)}}^2\right\}\\
        \leq&\frac{2}{\gamma}\left(k^* + {N^2\gamma^2}\sum_{i> k^*}{\lambda_i^{(q)}}^2\right),
    \end{aligned}
\end{equation*}
Hence,
\begin{equation*}
    I_1\leq \frac{4}{\gamma^2N^2}\frac{2(1+\tilde{\epsilon})\gamma\alpha_B\cdot\mathrm{tr}\left(\mathbf{B}_{0,N}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\left(k^* + {N^2\gamma^2}\sum_{i> k^*}{\lambda_i^{(q)}}^2\right).
\end{equation*}
Then we tackle $\mathrm{tr}(\mathbf{B}_{0,N})$.
\begin{equation}
    \begin{aligned}
        \mathrm{tr}(\mathbf{B}_{0,N})&=\mathrm{tr}\left(\mathbf{B}_{0}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N}\mathbf{B}_{0}(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N}\right)\\
        &=\sum_{i}\left(1-(1-\frac{\gamma}{2}\lambda_{i}^{(q)})^{2N}\right)\cdot\left(\langle\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*},\mathbf{v}_{i}^{(q)}\rangle\right)^{2}\\
        &\leq \sum_i\min\{1,N\gamma\lambda_i^{(q)}\}\left(\langle\mathbf{w}_0-{\mathbf{w}^{(q)}}^*,\mathbf{v}_i^{(q)}\rangle\right)^2\\
        &\leq \|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{I}_{0:k^{*}}}^{2}+N\gamma\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{H}_{k^{*}:\infty}}^{2}.
    \end{aligned}
\end{equation}
Therefore,
\begin{equation*}
    I_1\leq \frac{4}{\gamma^2N^2}\frac{2(1+\tilde{\epsilon})\gamma\alpha_B\cdot\left(\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{I}_{0:k^{*}}}^{2}+N\gamma\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{H}_{k^{*}:\infty}}^{2}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\left(k^* + {N^2\gamma^2}\sum_{i> k^*}{\lambda_i^{(q)}}^2\right).
\end{equation*}

Regarding $I_2$,
\begin{equation*}
    \begin{aligned}
        I_2=&\frac{2}{\gamma N^{2}}\sum_{k=0}^{N-1}\left\langle(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{k}-(\mathbf{I}-\frac{\gamma}{2}\mathbf{H}^{(q)})^{N+k},\mathbf{B}_{0}\right\rangle\\
        =&\frac{2}{\gamma N^{2}}\sum_{k=0}^{N-1}\sum_i\left[(1-\frac{\gamma}{2}\lambda_i^{(q)})^{k}-(1-\frac{\gamma}{2}\lambda_i^{(q)})^{N+k}\right]\omega_i^2\\
        =&\frac{4}{\gamma^2 N^{2}}\sum_i\left[1-(1-\frac{\gamma}{2}\lambda_i^{(q)})^{N}\right]^2\frac{\omega_i^2}{\lambda_i^{(q)}}\\
        \leq&\frac{4}{\gamma^2 N^{2}}\sum_i\frac{\omega_i^2}{\lambda_i^{(q)}}\operatorname*{min}\left\{1,\gamma^{2}N^{2}(\lambda_{i}^{(q)})^{2}\right\}\\
        =&\frac{4}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+4\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{{k^*}:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

Overall, 
\begin{equation*}
    \begin{aligned}
        &\mathrm{bias}\leq I_1+I_2\\
        \leq& \frac{8(1+\tilde{\epsilon})\alpha_B\cdot\left(\frac{\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{I}_{0:k^{*}}}^{2}}{N\gamma}+\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{H}_{k^{*}:\infty}}^{2}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N} + {N\gamma^2}\sum_{i> k^*}{\lambda_i^{(q)}}^2\right)\\
        +& \frac{4}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+4\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{{k^*}:\infty}^{(q)}}^2.
    \end{aligned}
\end{equation*}

\label{thm: master multiplicative}
Suppose there exist $\epsilon_d,\epsilon_l,\epsilon_p,\epsilon_a$ and $\epsilon_o$ such that for any $i\in \{d,l,p,a,o\}$, quantization $\mathcal{Q}_i$ is $\epsilon_i$-multiplicative. Under Assumption \ref{ass1}, Assumption \ref{ass: addd quantized}, Assumption \ref{ass2}, and Assumption \ref{ass3}, if the step size satisfies
\begin{equation*}
    1>2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)}),\quad 8\epsilon_p\leq \gamma \lambda_d^{(q)}-\frac{3}{4}\gamma^2{\lambda_d^{(q)}}^2,
\end{equation*}
then taking expectation over $\mathbf{w}^*$ on $\mathrm{variance}$ \footnote{Here we assume that $\mathbb{E}\mathbf{w}^*{\mathbf{w}^*}^\top=\mathbf{I}$.},
\begin{equation*}
    \begin{aligned}
        R_N^{(0)}/2\leq &\frac{4{\sigma_M^{(q)}}^2+32(1+\tilde{\epsilon}){d\epsilon_p}\alpha_B/\gamma}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\mathrm{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N}+N\gamma^2\cdot\sum_{i>k^*}(\lambda_i^{(q)})^2\right)\\
        +
        &\frac{16\epsilon_p}{\gamma}\left(\sum_{i\leq k^*}\frac{1}{N\gamma\lambda_i^{(q)}}+N\gamma\sum_{i>k^*}\lambda_i^{(q)}\right)\\
        +& \frac{8(1+\tilde{\epsilon})\alpha_B\cdot\left(\frac{\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{I}_{0:k^{*}}}^{2}}{N\gamma}+\|\mathbf{w}_{0}-{\mathbf{w}^{(q)}}^{*}\|_{\mathbf{H}_{k^{*}:\infty}}^{2}\right)}{1-2(1+\tilde{\epsilon})\gamma\alpha_B\operatorname{tr}(\mathbf{H}^{(q)})}\left(\frac{k^*}{N} + {N\gamma^2}\sum_{i> k^*}{\lambda_i^{(q)}}^2\right)\\
        +& \frac{4}{\gamma^2N^2}\cdot\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{(\mathbf{H}_{0:k^*}^{(q)})^{-1}}^2+4\|\mathbf{w}_0-{\mathbf{w}^{(q)}}^*\|_{\mathbf{H}_{{k^*}:\infty}^{(q)}}^2,
    \end{aligned}
\end{equation*}
where
\begin{gather*}
        \tilde{\epsilon}=8\epsilon_o(1+\epsilon_p)(1+\epsilon_a)+8\epsilon_p+4\epsilon_a(1+\epsilon_p),\\
        {\sigma_M^{(q)}}^2=\frac{(1+4\epsilon_o)\sigma^2}{B} + \frac{\mathbb{E}_{\mathbf{w}^*}\|\mathbf{w}^*\|_\mathbf{H}^2}{1+\epsilon_d}\alpha_B\left(4\epsilon_o[(1+\epsilon_p)(1+\epsilon_a)+1]+2\epsilon_a(1+\epsilon_p)+4\epsilon_p \right).
\end{gather*}
